-- ============================================================
--  042_cursos_calidad_farmaceutica.sql — La línea de Calidad
--
--  Diez cursos de calidad farmacéutica con su estructura completa:
--  cinco unidades cada uno, 338 clases en total, y en cada clase el
--  video, los documentos oficiales y el texto de apoyo que trae el
--  archivo de curaduría.
--
--  Cada enlace fue abierto antes de entrar aquí. Los videos borrados
--  o restringidos y los PDF que daban 404 se quedaron fuera: un
--  reproductor que dice «no disponible» dentro de una clase es peor
--  que no poner nada.
--
--  El archivo trae Unidad › Clase › Subclase y el Aula tiene dos
--  niveles. La subclase es el contenido real, así que es la que pasa
--  a ser clase; el nombre de la «Clase» del archivo se conserva en el
--  subtítulo para no perder ese nivel.
--
--  Quedan en BORRADOR: nada se publica solo.
-- ============================================================

-- ─── 1. Curso de Gestión de Calidad Farmacéutica (35 clases) ───
DO $curso$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  -- Si ya está, no se duplica.
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Gestión de Calidad Farmacéutica' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, level,
     objective, audience, duration_minutes, author_name, status, modality)
  VALUES ('edvanta', 'Curso de Gestión de Calidad Farmacéutica', 'Curso para diseñar, implementar y mejorar sistemas de gestión de calidad (SGC) en la industria y los servicios farmacéuticos colombianos. Integra ICH Q10, ISO 9001:2015 y el marco normativo nacional (INVIMA, Decreto 677/1995, Res. 1160/2016, Decreto 780/2016 y Res.', '<p>Curso para diseñar, implementar y mejorar sistemas de gestión de calidad (SGC) en la industria y los servicios farmacéuticos colombianos. Integra ICH Q10, ISO 9001:2015 y el marco normativo nacional (INVIMA, Decreto 677/1995, Res. 1160/2016, Decreto 780/2016 y Res. 1403/2007) con enfoque por procesos, indicadores, revisión por la dirección, gestión del cambio y cultura de calidad.</p><h3>Objetivo general</h3><p>Que el Químico Farmacéutico sea capaz de diseñar, implementar, medir y mejorar un sistema de gestión de calidad en una organización farmacéutica colombiana, integrando ICH Q10, ISO 9001:2015 y la normativa del INVIMA y MinSalud.</p><h3>A quién va dirigido</h3><p>Químicos Farmacéuticos, regentes de farmacia, directores técnicos, profesionales de aseguramiento de calidad y estudiantes de últimos semestres de Química Farmacéutica en Colombia.</p><h3>Contexto normativo</h3><p>Colombia — normativa INVIMA / MinSalud</p>',
          'Calidad farmacéutica', 'intermedio', 'Que el Químico Farmacéutico sea capaz de diseñar, implementar, medir y mejorar un sistema de gestión de calidad en una organización farmacéutica colombiana, integrando ICH Q10, ISO 9001:2015 y la normativa del INVIMA y MinSalud.', 'Químicos Farmacéuticos, regentes de farmacia, directores técnicos, profesionales de aseguramiento de calidad y estudiantes de últimos semestres de Química Farmacéutica en Colombia.',
          1200, 'Edvanta', 'borrador', 'asincronica')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos de la gestión de calidad farmacéutica', 0)
  RETURNING id INTO v_unidad;
