  VALUES (v_clase, 'texto', 0, '{"html":"<p>El estudiante conoce la ruta del curso, su alcance frente a los cursos hermanos (BPM, CAPA, auditoría, etc.) y por qué el QF colombiano necesita dominar el SGC.</p>"}'::jsonb);
