  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Hoja de ruta para implementar o fortalecer un SGC farmacéutico', 'Clase 4 · Cultura de calidad e implementación del SGC', 6, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Ejecuta un plan de implementación por fases (diagnóstico, compromiso, diseño, implementación, verificación, mejora) adaptado a la normativa colombiana.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=BKZ1PhzGvO0","provider":"youtube","videoId":"BKZ1PhzGvO0","title":"Rol del Sistema de Gestión de la Calidad SGC en la Industria Farmacéutica","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=2H6FD5z1fuM","provider":"youtube","videoId":"2H6FD5z1fuM","title":"Fases para implementar un Sistema de Gestión de la Calidad bajo la norma ISO 9001","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf","title":"ICH Q10 Pharmaceutical Quality System","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: diseñar una hoja de ruta para implementar o fortalecer un sistema de gestión de calidad en una organización farmacéutica colombiana, integrando lo aprendido en el curso.</p><p>Desarrollo. Implementar un SGC es un proyecto de cambio organizacional, no solo documental. Se recomienda una secuencia en seis fases.</p><p>Fase 1. Diagnóstico. Evaluar la brecha frente a los requisitos aplicables: Res. 1160/2016 para fabricantes, Decreto 780/2016 y Res. 1403/2007 para servicios farmacéuticos, ICH Q10 como buena práctica e ISO 9001 si se busca certificación. Herramienta: lista de chequeo con calificación cumple / cumple parcialmente / no cumple y evidencia.</p><p>Fase 2. Compromiso de la dirección. Presentar el diagnóstico a la gerencia, definir la política y los objetivos de calidad, nombrar al responsable del SGC y asignar presupuesto. Sin este paso, el sistema queda en manos de un solo departamento.</p><p>Fase 3. Diseño del sistema. Construir el mapa de procesos, caracterizar cada proceso, definir los indicadores y su ficha técnica, identificar riesgos y oportunidades y establecer la estructura documental (manual, procedimientos, instructivos, formatos y registros).</p><p>Fase 4. Implementación. Capacitar por roles, poner en marcha los procedimientos de gestión del cambio, CAPA, quejas, revisión de producto y control documental, y empezar a medir. Es normal que durante los primeros meses los indicadores \"empeoren\", porque por primera vez se registran desviaciones y quejas que antes no se veían.</p><p>Fase 5. Verificación. Auditorías internas, primera revisión por la dirección y, si aplica, autoinspección previa a la visita del INVIMA o a la auditoría de certificación.</p><p>Fase 6. Mejora y sostenibilidad. Plan de mejora anual, gestión del conocimiento y fortalecimiento de la cultura de calidad: reconocer reportes de desviaciones, medir la percepción del personal y lograr que los líderes den ejemplo.</p><p>Ejemplo aplicado. Un servicio farmacéutico de una IPS de mediana complejidad en Cali recibe en la visita de la secretaría de salud observaciones sobre trazabilidad de la dispensación y ausencia de indicadores. El QF director técnico realiza el diagnóstico frente a la Res. 1403/2007, presenta un plan de 9 meses a la gerencia, construye un mapa con procesos de selección, adquisición, recepción, almacenamiento, dispensación y farmacovigilancia, define 8 indicadores (por ejemplo, porcentaje de errores de dispensación y oportunidad de entrega) y programa la primera revisión por la dirección al sexto mes. En la siguiente visita, el servicio demuestra datos, acciones y mejora.</p><p>Puntos clave:<br>1. La implementación empieza con un diagnóstico de brechas contra la norma aplicable y el compromiso explícito de la dirección.<br>2. El SGC se diseña desde los procesos, no desde los documentos; la documentación describe procesos que ya están definidos.<br>3. La sostenibilidad depende de medir, revisar y construir una cultura donde reportar problemas sea valorado.</p>"}'::jsonb);

END
$curso$;

-- ─── 2. Curso de Aseguramiento de la Calidad Farmacéutica (35 clases) ───
DO $curso$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  -- Si ya está, no se duplica.
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Aseguramiento de la Calidad Farmacéutica' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, level,
     objective, audience, duration_minutes, author_name, status, modality)
  VALUES ('edvanta', 'Curso de Aseguramiento de la Calidad Farmacéutica', 'Curso práctico sobre la función de Aseguramiento de la Calidad (QA) en la empresa farmacéutica colombiana. Cubre la diferencia QA/QC, la liberación de lotes, la revisión de registros y la RAP, el control de cambios, los proveedores, las quejas, las devoluciones y el recall, la calificación y validación, la integridad de datos y la interfaz con farmacovigilancia y…', '<p>Curso práctico sobre la función de Aseguramiento de la Calidad (QA) en la empresa farmacéutica colombiana. Cubre la diferencia QA/QC, la liberación de lotes, la revisión de registros y la RAP, el control de cambios, los proveedores, las quejas, las devoluciones y el recall, la calificación y validación, la integridad de datos y la interfaz con farmacovigilancia y tecnovigilancia, bajo el marco INVIMA.</p><h3>Objetivo general</h3><p>Que el Químico Farmacéutico comprenda y aplique los procesos de Aseguramiento de la Calidad necesarios para garantizar que cada lote liberado cumpla los requisitos de calidad, seguridad y eficacia, conforme a la normativa colombiana (Decreto 677/1995, Resolución 1160/2016 y regulación INVIMA de vigilancia) y a los referentes OMS, PIC/S e ICH.</p><h3>A quién va dirigido</h3><p>Químicos Farmacéuticos, estudiantes de último semestre de Química Farmacéutica y profesionales de calidad, producción y asuntos regulatorios de laboratorios farmacéuticos, titulares de registro sanitario y fabricantes por contrato en Colombia.</p><h3>Contexto normativo</h3><p>Colombia — normativa INVIMA / MinSalud</p>',
          'Calidad farmacéutica', 'intermedio', 'Que el Químico Farmacéutico comprenda y aplique los procesos de Aseguramiento de la Calidad necesarios para garantizar que cada lote liberado cumpla los requisitos de calidad, seguridad y eficacia, conforme a la normativa colombiana (Decreto 677/1995, Resolución 1160/2016 y regulación INVIMA de vigilancia) y a los referentes OMS, PIC/S e ICH.', 'Químicos Farmacéuticos, estudiantes de último semestre de Química Farmacéutica y profesionales de calidad, producción y asuntos regulatorios de laboratorios farmacéuticos, titulares de registro sanitario y fabricantes por contrato en Colombia.',
          1200, 'Edvanta', 'borrador', 'asincronica')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos del Aseguramiento de la Calidad farmacéutica y marco normativo colombiano', 0)
