  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Control de cambios, proveedores, quejas, devoluciones y retiro del mercado', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Introducción: QA a lo largo del ciclo de vida del producto', 'Clase 1 · Introducción a la unidad', 0, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Resume cómo control de cambios, proveedores y gestión de quejas, devoluciones y retiros protegen el producto antes y después de su liberación.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=LrZXJviTK3U&pp=ygUVI2NhbGlkYWRlbmxhaW5kdXN0cmlh","provider":"youtube","videoId":"LrZXJviTK3U","title":"Aseguramiento de la calidad en la industria farmacéutica","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf","title":"ICH Q10 Pharmaceutical Quality System","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://database.ich.org/sites/default/files/Q12_Guideline_Step4_2019_1119.pdf","title":"ICH Q12 Technical and Regulatory Considerations for Pharmaceutical Product Lifecycle Management","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: Comprender por qué el control de cambios, la gestión de proveedores y la gestión de quejas, devoluciones y retiros del mercado conforman el bloque de Aseguramiento de Calidad que protege al producto antes y después de su liberación.</p><p>Desarrollo: En las unidades anteriores el foco estuvo en el lote: cómo se revisa y quién lo libera. Esta unidad amplía la mirada al ciclo de vida del producto. Un medicamento puede fabricarse correctamente y aun así fallar si cambia, sin evaluación, un proveedor de excipiente, un equipo o un método; o si la empresa no reacciona a tiempo cuando un paciente, una IPS o un distribuidor reporta un problema. Por eso las BPM de la OMS adoptadas en Colombia por la Resolución 1160 de 2016 exigen sistemas formales para el control de cambios, la aprobación y seguimiento de proveedores, la gestión de quejas, el manejo de productos devueltos y el retiro de producto del mercado.</p><p>La lógica común de estos procesos es la misma: (1) detectar, (2) evaluar el impacto sobre la calidad, la seguridad del paciente y el registro sanitario, (3) decidir con criterio técnico documentado y (4) verificar la eficacia de lo decidido. QA no ejecuta todas las tareas (compras califica comercialmente al proveedor, logística recoge las devoluciones, producción implementa el cambio), pero sí es dueña de la decisión de calidad y del registro que la respalda.</p><p>En Colombia esto tiene una dimensión regulatoria concreta: los cambios que afectan condiciones aprobadas del registro sanitario (Decreto 677 de 1995) deben tramitarse ante INVIMA, y los retiros de mercado y alertas sanitarias se gestionan en coordinación con el Grupo de Farmacovigilancia de INVIMA, cuyo marco actual incluye la Resolución 2024015321 de 2024 y su guía de gestión de alertas sanitarias.</p><p>Ejemplo aplicado: Un laboratorio de Medellín recibe tres quejas en un mes por tabletas partidas en blíster de un antihipertensivo. QA las agrupa, revisa los registros de lote y descubre que coinciden con un cambio de proveedor de material de empaque aprobado sin evaluar la resistencia del aluminio. Una sola historia toca los tres temas de la unidad: proveedor, control de cambios y quejas, con una posible decisión de retiro.</p><p>Puntos clave:<br>1. Los procesos de esta unidad protegen el producto a lo largo de su ciclo de vida, no solo en la liberación.<br>2. QA es dueña de la decisión de calidad, aunque otras áreas ejecuten las tareas.<br>3. En Colombia, varios de estos eventos tienen consecuencias regulatorias ante INVIMA.</p>"}'::jsonb);
