  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Evaluación de impacto y cambios con efecto en el registro sanitario', 'Clase 2 · Control de cambios', 2, 'video')
