  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=Xkg4bmOdsVk","provider":"youtube","videoId":"Xkg4bmOdsVk","title":"Pharma Supplier Qualification: Audits, Quality Agreements, Change Control & Supply Chain Controls","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/contract-manufacturing-arrangements-drugs-quality-agreements-guidance-industry","title":"[Página web] Contract Manufacturing Arrangements for Drugs: Quality Agreements – Guidance for Industry","description":"FDA (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm","title":"[Página web] Resolución 1160 de 2016 (Manuales de BPM e inspección)","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: Explicar el contenido de un acuerdo de calidad con proveedores y fabricantes por contrato y cómo QA hace seguimiento continuo de su desempeño.</p><p>Desarrollo: Calificar a un proveedor es el inicio, no el final. Una vez aprobado, la relación debe formalizarse en un acuerdo técnico o de calidad que delimite responsabilidades. Las BPM de la OMS adoptadas por la Resolución 1160 de 2016 exigen que las actividades contratadas (fabricación, análisis, almacenamiento) estén definidas en un contrato escrito, que el contratante evalúe la competencia del contratado y que el contratado no subcontrate sin autorización. Un acuerdo de calidad típico incluye: alcance y productos; responsabilidades de cada parte en especificaciones, muestreo y análisis; quién libera; manejo de desviaciones, OOS y quejas; notificación obligatoria de cambios (sitio, proceso, ruta de síntesis, proveedor de origen); derecho a auditar; retención de muestras y registros; y la cadena de comunicación ante un retiro de mercado.</p><p>El seguimiento se basa en indicadores revisados periódicamente: porcentaje de lotes rechazados en recepción, entregas con documentación incompleta, quejas atribuibles al material, tiempo de respuesta ante desviaciones y resultados de auditorías. Con esta información QA asigna un nivel de riesgo (por ejemplo, alto, medio, bajo) que define la frecuencia de auditoría y la intensidad del análisis en recepción (análisis completo frente a análisis reducido con certificado de análisis). Un proveedor puede pasar de \"aprobado\" a \"aprobado condicionado\" o \"suspendido\" según su desempeño, y esa decisión debe estar documentada en la lista de proveedores aprobados.</p><p>Ejemplo aplicado: Una empresa titular de registros en Barranquilla terceriza la fabricación de una suspensión pediátrica con un fabricante certificado en BPM por INVIMA. El acuerdo de calidad establece que el fabricante realiza el análisis completo y emite el certificado, pero la liberación al mercado la hace el QF de QA del titular. Durante la RAP, QA observa que dos lotes tuvieron desviaciones de viscosidad notificadas fuera del plazo acordado. Se programa una auditoría, se exige un plan de acción y el fabricante queda en estado \"aprobado condicionado\" hasta verificar su cumplimiento.</p><p>Puntos clave:<br>1. Todo proveedor crítico o fabricante por contrato debe tener un acuerdo de calidad escrito y vigente.<br>2. La notificación de cambios por parte del proveedor es una cláusula indispensable.<br>3. El estado del proveedor se ajusta según indicadores de desempeño y auditorías, con decisión documentada por QA.</p>"}'::jsonb);
