  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica de forma integrada revisión de lote, integridad de datos, quejas, recall y control de cambios en un caso colombiano.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=2FbcZA6nmG4","provider":"youtube","videoId":"2FbcZA6nmG4","title":"X Encuentro Nacional de Farmacovigilancia – Día 1","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=855CYrFdaVk","provider":"youtube","videoId":"855CYrFdaVk","title":"Invima ordena retiro de Vitafer y otros potenciadores por químico no autorizado","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: Aplicar de manera integrada los procesos de QA estudiados en el curso a un caso que va desde una señal de seguridad hasta la decisión de retiro de producto y el cierre con INVIMA.</p><p>Desarrollo: La farmacovigilancia y la tecnovigilancia generan información que QA no puede ignorar: un evento adverso o un incidente con un dispositivo puede ser la primera señal de un defecto de calidad. El trabajo de QA consiste en convertir esa señal en una investigación de calidad estructurada: (1) recibir el caso y registrar producto, lote, fecha y descripción; (2) determinar si existe un posible defecto de calidad o si es un evento propio del perfil de seguridad del producto; (3) revisar el registro de lote, las desviaciones, los resultados de Control de Calidad, las muestras de retención y las quejas previas del mismo lote; (4) evaluar el riesgo para el paciente; (5) decidir: cerrar sin acción, ampliar la investigación, poner en cuarentena el inventario o retirar el producto del mercado; (6) comunicar a INVIMA y a la red de distribución según corresponda; (7) verificar la eficacia del retiro mediante la conciliación de unidades distribuidas y recuperadas; y (8) registrar todo en la revisión anual de producto.</p><p>Caso aplicado: Una IPS de Bucaramanga reporta en el programa institucional de farmacovigilancia dos casos de flebitis en pacientes que recibieron un antibiótico inyectable del mismo lote. El titular recibe el reporte y el Grupo de Farmacovigilancia lo traslada a QA. QA revisa el registro de lote y encuentra una desviación cerrada sobre un filtro esterilizante reemplazado durante el llenado. Solicita análisis de partículas y endotoxinas de las muestras de retención; los resultados de partículas visibles están fuera de especificación. QA, con la dirección técnica, decide el retiro voluntario del lote, inicia la notificación a INVIMA dentro de los plazos aplicables (el marco de alertas sanitarias de la Resolución 2024015321 de 2024 y su guía de implementación fijan tiempos de reporte), comunica a distribuidores e IPS, controla las unidades recuperadas y las dispone como producto rechazado. Finalmente se abre una CAPA sobre el procedimiento de cambio de filtros y se reevalúa la validación del proceso aséptico.</p><p>Lectura del caso: Cada paso se apoya en un proceso del curso: farmacovigilancia (detección), revisión de registros de lote (investigación), integridad de datos (confiabilidad de la evidencia), quejas y recall (acción en el mercado), control de cambios y validación (corrección del proceso) y RAP (aprendizaje anual).</p><p>Puntos clave:<br>1. Un evento adverso puede ser la primera señal de un defecto de calidad; QA debe evaluarlo con el lote en la mano.<br>2. La decisión de retiro se basa en riesgo para el paciente y se documenta con evidencia trazable.<br>3. El cierre no es la recuperación del producto: requiere conciliación, notificación a INVIMA y acciones sobre la causa raíz.</p>"}'::jsonb);

END
$curso$;

-- ─── 3. Curso de Control de Calidad de Medicamentos (35 clases) ───
DO $curso$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  -- Si ya está, no se duplica.
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Control de Calidad de Medicamentos' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, level,
     objective, audience, duration_minutes, author_name, status, modality)
  VALUES ('edvanta', 'Curso de Control de Calidad de Medicamentos', 'Curso práctico sobre el trabajo del laboratorio de control de calidad de medicamentos en Colombia: especificaciones y farmacopeas, muestreo, análisis fisicoquímicos e instrumentales, control microbiológico, estudios de estabilidad para la zona climática IVb y gestión de resultados OOS/OOT hasta la liberación analítica.', '<p>Curso práctico sobre el trabajo del laboratorio de control de calidad de medicamentos en Colombia: especificaciones y farmacopeas, muestreo, análisis fisicoquímicos e instrumentales, control microbiológico, estudios de estabilidad para la zona climática IVb y gestión de resultados OOS/OOT hasta la liberación analítica. Todo el contenido se alinea con la Resolución 3619 de 2013 (BPL), la Resolución 1160 de 2016 y los requisitos del INVIMA.</p><h3>Objetivo general</h3><p>Capacitar al Químico Farmacéutico para planear, ejecutar, interpretar y documentar los análisis de control de calidad de materias primas, materiales de envase y productos terminados, de acuerdo con las farmacopeas oficiales y la normativa colombiana vigente, hasta emitir una decisión de liberación analítica confiable.</p><h3>A quién va dirigido</h3><p>Químicos Farmacéuticos, analistas y jefes de laboratorio de control de calidad, estudiantes de últimos semestres de Química Farmacéutica y profesionales de laboratorios fabricantes o externos certificados en BPL en Colombia.</p><h3>Contexto normativo</h3><p>Colombia — normativa INVIMA / MinSalud</p>',
          'Calidad farmacéutica', 'intermedio', 'Capacitar al Químico Farmacéutico para planear, ejecutar, interpretar y documentar los análisis de control de calidad de materias primas, materiales de envase y productos terminados, de acuerdo con las farmacopeas oficiales y la normativa colombiana vigente, hasta emitir una decisión de liberación analítica confiable.', 'Químicos Farmacéuticos, analistas y jefes de laboratorio de control de calidad, estudiantes de últimos semestres de Química Farmacéutica y profesionales de laboratorios fabricantes o externos certificados en BPL en Colombia.',
          1200, 'Edvanta', 'borrador', 'asincronica')
  RETURNING id INTO v_curso;

