  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 5. Resultados fuera de especificación y liberación analítica', 4)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Introducción a la unidad: del dato a la decisión', 'Clase 1 · Introducción a la unidad', 0, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Resume cómo los resultados analíticos se convierten en una decisión de calidad y por qué OOS, OOT y la liberación analítica exigen rigor documental.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=uhmbFrPcZlA","provider":"youtube","videoId":"uhmbFrPcZlA","title":"Gestión eficaz de desviaciones y resultados fuera de especificaciones (OOS)","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=7Z0-znzu_ws","provider":"youtube","videoId":"7Z0-znzu_ws","title":"OOS vs OOT in Pharma","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.fda.gov/media/158416/download","title":"Investigating Out-of-Specification (OOS) Test Results for Pharmaceutical Production (Rev. 1, 2022)","description":"FDA (EN) · misma fuente, URL buena tomada de otra fila del archivo"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: comprender cómo se transforma un conjunto de datos analíticos en una decisión de calidad y por qué los resultados atípicos (OOS y OOT) y la liberación analítica son el punto culminante del trabajo del laboratorio de control de calidad.</p><p>Desarrollo: en las unidades anteriores el estudiante aprendió a definir especificaciones, muestrear, analizar por técnicas fisicoquímicas e instrumentales, ejecutar ensayos microbiológicos y diseñar estudios de estabilidad. Todo ese esfuerzo converge en una pregunta: ¿el lote cumple y puede liberarse? Para responderla, el laboratorio debe garantizar que cada resultado sea confiable, trazable e íntegro. Un resultado fuera de especificación (OOS, por sus siglas en inglés) es aquel que cae por fuera de los criterios de aceptación aprobados en el registro sanitario, la farmacopea oficial o la especificación interna. Un resultado fuera de tendencia (OOT) cumple la especificación, pero se aparta del comportamiento esperado del producto, por ejemplo en una serie de datos de estabilidad o en el histórico de lotes. Ninguno de los dos puede descartarse sin investigación documentada.</p><p>La Resolución 3619 de 2013, que adopta el manual de Buenas Prácticas de Laboratorio de control de calidad basado en la OMS, exige que el laboratorio cuente con procedimientos para investigar resultados fuera de especificación, revisar los registros analíticos antes de emitir un informe y conservar los datos primarios. La visión de este curso es la del laboratorio: la fase I de la investigación (verificación de cálculos, equipos, estándares, soluciones y ejecución del analista) es responsabilidad directa del jefe de laboratorio y del analista. Las fases posteriores, el análisis de causa raíz en producción y las acciones correctivas y preventivas se profundizan en los cursos hermanos de CAPA y Gestión de Riesgos.</p><p>La liberación analítica es la declaración, por parte de control de calidad, de que el lote cumple todas las especificaciones; se documenta mediante el certificado de análisis. La liberación final del lote al mercado la realiza la persona autorizada dentro del sistema de calidad, según la Resolución 1160 de 2016, considerando además la revisión de la documentación de fabricación.</p><p>Ejemplo aplicado: un laboratorio fabricante en Bogotá analiza un lote de tabletas de metformina 850 mg. La valoración por HPLC arroja 93,8 % frente a una especificación de 95,0–105,0 %. Antes de cualquier repetición, el analista informa al jefe de laboratorio, se conservan las soluciones y se inicia la fase I. Si se demuestra un error de dilución documentado, el resultado se invalida y se repite; si no, el caso escala a investigación completa y el lote queda en cuarentena. Durante una inspección del INVIMA, este expediente será uno de los primeros documentos revisados.</p><p>Puntos clave:<br>1. Un OOS nunca se repite «hasta que cumpla»: toda repetición debe estar justificada por una investigación documentada.<br>2. Un OOT es una señal temprana; detectarlo protege la vida útil declarada y evita futuros OOS en estabilidad.<br>3. La liberación analítica se apoya en datos íntegros, revisados y trazables, y es la base de la liberación final del lote.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Investigación de resultados fuera de especificación (OOS): fase I de laboratorio', 'Clase 2 · Resultados OOS y OOT en el laboratorio', 1, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
