  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Resultados fuera de tendencia (OOT) en estabilidad y lotes', 'Clase 2 · Resultados OOS y OOT en el laboratorio', 2, 'video')
