  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Revisión de datos y certificado de análisis', 'Clase 3 · Liberación analítica', 3, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica la revisión de datos primarios y la elaboración del certificado de análisis con los elementos exigidos por la normativa.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=7LX_9A933JQ","provider":"youtube","videoId":"7LX_9A933JQ","title":"What is the Certificate of Analysis(CoA)in pharma?","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3619_2013.htm","title":"[Página web] Resolución 3619 de 2013 (texto compilado en el normograma INVIMA)","description":"Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Liberación analítica de un lote: caso integrador', 'Clase 3 · Liberación analítica', 4, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Integra los contenidos del curso para decidir la liberación analítica de un lote y documentarla conforme a la Res. 3619/2013 y la Res. 1160/2016.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=_BQS2pqleqU","provider":"youtube","videoId":"_BQS2pqleqU","title":"Guía de inspección BPM – Revisión periódica de producto y Liberación de producto (DIGEMID, Perú)","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.fda.gov/media/158416/download","title":"Investigating Out-of-Specification (OOS) Test Results for Pharmaceutical Production (Rev. 1, 2022)","description":"FDA (EN) · misma fuente, URL buena tomada de otra fila del archivo"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3619_2013.htm","title":"[Página web] Resolución 3619 de 2013 – Manual de BPL de control de calidad de productos farmacéuticos","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: aplicar de forma integrada los conocimientos del curso para emitir una decisión de liberación analítica de un lote, documentándola conforme a la normativa colombiana.</p><p>Desarrollo: la liberación analítica no es un acto aislado al final del análisis, sino un proceso con etapas definidas. Primero, el laboratorio verifica que se ejecutaron todos los ensayos exigidos por la especificación aprobada en el registro sanitario (identificación, valoración, impurezas, disolución, uniformidad de dosis, pruebas microbiológicas, entre otros) y que se usó la edición vigente de la farmacopea oficial o el método validado. Segundo, se realiza la revisión de datos: un segundo analista o el supervisor comprueba cálculos, idoneidad del sistema cromatográfico, vigencia de estándares de referencia, calibración y calificación de equipos, preparación de reactivos y coherencia entre datos primarios electrónicos y registros en papel. Tercero, se confirma que no existen OOS abiertos ni desviaciones de laboratorio pendientes que afecten el lote. Cuarto, se emite el certificado de análisis, que debe incluir identificación del producto y lote, fecha de análisis, referencias a especificación y métodos, resultados numéricos con sus límites, conclusión de cumple o no cumple, y la firma de la persona responsable. Finalmente, el lote cambia de estado en el sistema (por ejemplo, de cuarentena a aprobado analíticamente) y pasa a la persona autorizada para la liberación final, según la Resolución 1160 de 2016.</p><p>La Resolución 3619 de 2013 exige que los informes de análisis sean revisados y aprobados, que los datos primarios se conserven y que cualquier corrección sea trazable. En un laboratorio externo certificado en BPL por el INVIMA, el certificado de análisis es además el producto contractual que se entrega al titular del registro.</p><p>Ejemplo aplicado (caso integrador): un laboratorio de Medellín recibe para liberación un lote de suspensión oral de amoxicilina 250 mg/5 mL. La especificación incluye aspecto, pH, valoración por HPLC, uniformidad de dosis en envase multidosis, recuento microbiano, ausencia de Escherichia coli y volumen entregable. Todos los resultados cumplen, pero en la revisión de datos el supervisor detecta que el estándar secundario de amoxicilina tenía la recalificación vencida dos días antes del análisis. La decisión correcta no es firmar el certificado: se abre una desviación de laboratorio, se evalúa el impacto con un estándar vigente y solo con evidencia documentada se procede a la liberación analítica. El estudiante debe redactar el certificado de análisis y la nota de revisión de este caso.</p><p>Puntos clave:<br>1. Liberar analíticamente es certificar que todos los ensayos de la especificación vigente se ejecutaron correctamente y cumplen.<br>2. La revisión de datos por una segunda persona es el filtro que detecta errores antes de que lleguen al paciente o al inspector.<br>3. Ninguna desviación ni OOS abierto puede quedar pendiente al firmar un certificado de análisis.</p>"}'::jsonb);

