  VALUES ('edvanta', 'Curso de Buenas Prácticas de Manufactura — BPM', 'Curso práctico sobre las Buenas Prácticas de Manufactura de medicamentos en Colombia: desde su historia y el marco OMS/PIC/S hasta la Resolución 1160 de 2016, las normas especiales y la certificación del INVIMA. Cubre personal, instalaciones, equipos, sistemas de apoyo crítico, producción, productos estériles, materiales, contratos y autoinspección.', '<p>Curso práctico sobre las Buenas Prácticas de Manufactura de medicamentos en Colombia: desde su historia y el marco OMS/PIC/S hasta la Resolución 1160 de 2016, las normas especiales y la certificación del INVIMA. Cubre personal, instalaciones, equipos, sistemas de apoyo crítico, producción, productos estériles, materiales, contratos y autoinspección.</p><h3>Objetivo general</h3><p>Que el Químico Farmacéutico interprete y aplique los requisitos de BPM vigentes en Colombia en las operaciones de fabricación de medicamentos y prepare a su organización para obtener y mantener la certificación BPM del INVIMA.</p><h3>A quién va dirigido</h3><p>Químicos Farmacéuticos, estudiantes de últimos semestres de Química Farmacéutica, y profesionales de producción, aseguramiento de calidad y asuntos regulatorios de laboratorios fabricantes en Colombia.</p><h3>Contexto normativo</h3><p>Colombia — normativa INVIMA / MinSalud</p>',
          'Calidad farmacéutica', 'intermedio', 'Que el Químico Farmacéutico interprete y aplique los requisitos de BPM vigentes en Colombia en las operaciones de fabricación de medicamentos y prepare a su organización para obtener y mantener la certificación BPM del INVIMA.', 'Químicos Farmacéuticos, estudiantes de últimos semestres de Química Farmacéutica, y profesionales de producción, aseguramiento de calidad y asuntos regulatorios de laboratorios fabricantes en Colombia.',
          1200, 'Edvanta', 'borrador', 'asincronica')
  RETURNING id INTO v_curso;

