  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Despeje de línea', 'Clase 3 · Operaciones de producción', 3, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Ejecuta el despeje de línea entre lotes con verificación independiente y registro en el batch record.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=mTC-M11FUQw","provider":"youtube","videoId":"mTC-M11FUQw","title":"Curso-Taller Buenas Prácticas de Manufactura (BPM-GMP) en la Industria Farmacéutica (Parte 1)","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm","title":"[Página web] Resolución 1160 de 2016 (Manuales de BPM e inspección)","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: que el estudiante comprenda y sepa ejecutar el despeje de línea (line clearance) como control BPM para evitar mezclas y confusiones entre lotes y productos.</p><p>Desarrollo: el despeje de línea es la verificación documentada de que un área, equipo o línea de producción o empaque está libre de materiales, producto, documentos y rótulos del lote anterior antes de iniciar uno nuevo. Los manuales de BPM adoptados por la Resolución 1160 de 2016 (basados en los informes técnicos de la OMS) exigen que, antes de cualquier operación de fabricación o envasado, se compruebe que el área y los equipos estén limpios y libres de materiales y documentos que no se requieran para la operación planificada, y que esta comprobación quede registrada. Las mezclas (mix-ups) siguen siendo una de las causas más frecuentes de retiros de producto del mercado, sobre todo en acondicionamiento, donde conviven blísteres, plegadizas, insertos y etiquetas muy parecidos.</p><p>Un despeje robusto incluye: (1) retiro de todo el material del lote anterior (granel, producto terminado, material de envase impreso sobrante, muestras y rechazos), con su conciliación; (2) retiro de documentos y rótulos del lote anterior; (3) verificación del estado de limpieza del área y los equipos según el procedimiento y la etiqueta de estado (\"limpio\", con fecha y responsable); (4) revisión de puntos ocultos (tolvas, guías, alimentadores, cajas de rechazo, pisos bajo la máquina, cintas transportadoras); (5) identificación de la línea con el nombre del producto, la concentración y el número del lote que inicia; y (6) doble verificación: la ejecuta producción y la confirma una segunda persona, normalmente de aseguramiento de calidad, con firma y fecha en el registro de lote.</p><p>Ejemplo aplicado: en una planta de sólidos orales en Bogotá se empacan en la misma blistera dos concentraciones de losartán (50 mg y 100 mg). Al terminar el lote de 50 mg, el operario retira el material impreso y el auditor de calidad revisa la línea con una lista de chequeo y encuentra dos plegadizas de 50 mg atrapadas en el alimentador. El hallazgo se registra, se corrige y se repite la verificación antes de liberar la línea. En una visita de certificación, el inspector del INVIMA suele revisar el registro de despeje dentro del batch record y puede pedir que se haga uno en vivo; si no hay doble verificación o la lista de chequeo es genérica, la deficiencia suele considerarse mayor por el riesgo de mezcla.</p><p>Puntos clave:<br>1. El despeje de línea se hace antes de cada operación y entre lotes, se documenta y lo verifica una segunda persona independiente.<br>2. Debe cubrir materiales, documentos, rótulos y puntos ocultos del equipo, y no solo la limpieza visible.<br>3. Las listas de chequeo específicas para cada línea o equipo, junto con la conciliación del material impreso, son la mejor defensa contra las mezclas.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Rendimientos y conciliación de materiales', 'Clase 3 · Operaciones de producción', 4, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica el cálculo de rendimientos y la conciliación del material impreso, y decide qué hacer cuando están fuera de límites.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=JwRhfZ-vcIM","provider":"youtube","videoId":"JwRhfZ-vcIM","title":"BPM Industria farmacéutica","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm","title":"[Página web] Resolución 1160 de 2016 (Manuales de BPM e inspección)","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: que el estudiante interprete los rendimientos teóricos y reales y la conciliación de materiales como herramientas BPM para detectar pérdidas, mezclas o desviaciones en un lote.</p><p>Desarrollo: los manuales de BPM de la Resolución 1160 de 2016 piden que en cada etapa importante de la producción se registre el rendimiento real y se compare con el teórico, y que cualquier diferencia fuera de los límites establecidos se investigue antes de liberar el lote. El rendimiento teórico es la cantidad que se obtendría si no hubiera pérdidas; el rendimiento real es lo que efectivamente se obtiene; y el porcentaje de rendimiento se calcula como (real / teórico) x 100. Los límites de aceptación (por ejemplo, un rango para la granulación, la compresión o el envasado) se definen a partir de los datos históricos y de la validación del proceso, y deben quedar en la orden maestra de producción.</p><p>La conciliación va más allá del rendimiento: es el balance entre lo entregado y lo usado, lo devuelto, lo rechazado y lo destruido. Es obligatoria para el material de envase impreso (etiquetas, plegadizas, insertos, foil impreso), porque un faltante puede significar que un rótulo terminó en otro producto. Si la conciliación del material impreso no cuadra, el lote no se libera hasta investigar.</p><p>Cuando el rendimiento o la conciliación salen de los límites se abre una desviación: se evalúan las posibles causas (errores de pesaje, pérdidas en equipos, derrames, muestras no registradas, errores de cálculo o mezclas), su impacto en la calidad y su posible extensión a otros lotes. La investigación detallada y las acciones correctivas se trabajan en los cursos de CAPA y de Gestión de Riesgos; en este curso lo importante es reconocer el requisito BPM y la decisión que dispara.</p><p>Ejemplo aplicado: un laboratorio en Medellín fabrica un lote de 500.000 tabletas de metformina. El rendimiento esperado de la compresión está entre 97 % y 100,5 %, y el real da 94,2 %. El supervisor documenta la desviación en el registro de lote; la investigación encuentra que no se registraron las tabletas retiradas en un ajuste de peso. Además, la conciliación de plegadizas muestra 120 unidades faltantes, que aparecen en la caja de rechazos de la línea. Ambas situaciones quedan documentadas y QA decide sobre la liberación. Durante una visita, el INVIMA puede revisar varios registros de lote para comprobar que los rendimientos se calculan, se comparan con los límites y que las desviaciones se cierran antes de la liberación.</p><p>Puntos clave:<br>1. Rendimiento (%) = real / teórico x 100; los límites deben estar definidos en la orden maestra y basarse en datos del proceso.<br>2. La conciliación del material de envase impreso es obligatoria y un descuadre bloquea la liberación.<br>3. Todo resultado fuera de límites genera una desviación investigada y documentada antes de liberar el lote.</p>"}'::jsonb);
