  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.ministeriodesalud.go.cr/index.php/biblioteca-de-archivos-left/documentos-ministerio-de-salud/tramites/permisos-a-establecimientos/guias-de-inspeccion/1746-guia-de-verificacion-de-buenas-practicas-de-manufactura-bpm-para-la-industria-farmaceutica/file","title":"Guía de verificación de BPM para la industria farmacéutica (Ministerio de Salud de Costa Rica)","description":"MinSalud Costa Rica (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www3.paho.org/hq/dmdocuments/2008/1_Anexo_1_informe_32.pdf","title":"Informe 32 OMS - Anexo 1: Prácticas adecuadas de fabricación de productos farmacéuticos","description":"OPS/OMS (ES)"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Material de envase, rotulado, rechazos y devoluciones', 'Clase 4 · Materiales y almacenamiento', 7, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Describe los requisitos para el material impreso, los productos rechazados, las devoluciones y la destrucción documentada.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=nxcbKKOPCdc","provider":"youtube","videoId":"nxcbKKOPCdc","title":"Buenas Prácticas de Acondicionamiento / Empaque","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm","title":"[Página web] Resolución 1160 de 2016 (Manuales de BPM e inspección)","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: que el estudiante describa los requisitos BPM para el material de envase y empaque, el rotulado y el manejo de materiales rechazados, devueltos y retirados.</p><p>Desarrollo: los manuales de BPM de la Resolución 1160 de 2016 dan a los materiales de envase el mismo rigor que a las materias primas. Deben comprarse a proveedores aprobados según especificaciones, y cada recepción se revisa, se identifica con un número de lote interno, se pone en cuarentena y se muestrea antes de que control de calidad la apruebe. El material impreso (etiquetas, plegadizas, insertos, foil) es crítico porque contiene la información del producto, así que debe guardarse en condiciones seguras y con acceso restringido, se entrega a producción solo con autorización y en las cantidades necesarias, y se concilia al final del proceso. Las etiquetas sueltas se manejan en contenedores cerrados para evitar mezclas, y el material impreso obsoleto se destruye de forma documentada.</p><p>El rotulado de estado es parte de este control: cada material o recipiente debe mostrar su estado (cuarentena, aprobado, rechazado) con etiquetas o sistemas informáticos validados, y el codificado de lote y vencimiento en línea se verifica al inicio y durante el envasado.</p><p>Los materiales y productos rechazados se identifican de forma clara, se guardan separados en un área restringida y se devuelven al proveedor, se reprocesan (solo si está autorizado y documentado) o se destruyen. Los productos devueltos del mercado solo se reincorporan al inventario si control de calidad lo evalúa y comprueba que su calidad no se ha visto afectada (almacenamiento, tiempo, estado del envase); si hay dudas, se destruyen. Los retiros de producto del mercado siguen un procedimiento propio y, en Colombia, se coordinan con el INVIMA.</p><p>Ejemplo aplicado: un laboratorio en Cali recibe plegadizas para un jarabe pediátrico. El inspector de recepción ve que el texto del registro sanitario no coincide con el arte aprobado. El lote se rotula como \"rechazado\", se lleva al área de rechazos bajo llave y se notifica al proveedor. Dos meses después llega una devolución de un distribuidor con cajas expuestas a humedad: QA decide destruirla y deja acta de destrucción. Estos registros son los que el inspector del INVIMA suele revisar cuando recorre el almacén.</p><p>Puntos clave:<br>1. El material de envase impreso se recibe, se aprueba, se guarda con acceso restringido, se entrega controlado y se concilia como un material crítico.<br>2. Todo material debe mostrar su estado (cuarentena, aprobado, rechazado), y los rechazados se guardan separados y con acceso restringido.<br>3. Las devoluciones solo vuelven al inventario si QA evalúa y documenta que su calidad no se afectó; si hay duda, se destruyen.</p>"}'::jsonb);

