-- ─── 5. Curso de Buenas Prácticas de Laboratorio — BPL (35 clases) ───
DO $curso$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  -- Si ya está, no se duplica.
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Buenas Prácticas de Laboratorio — BPL' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, level,
     objective, audience, duration_minutes, author_name, status, modality)
  VALUES ('edvanta', 'Curso de Buenas Prácticas de Laboratorio — BPL', 'Curso práctico sobre las Buenas Prácticas de Laboratorio aplicables a los laboratorios de control de calidad de productos farmacéuticos en Colombia, según la Resolución 3619 de 2013, los principios BPL de la OCDE y la ISO/IEC 17025:2017.', '<p>Curso práctico sobre las Buenas Prácticas de Laboratorio aplicables a los laboratorios de control de calidad de productos farmacéuticos en Colombia, según la Resolución 3619 de 2013, los principios BPL de la OCDE y la ISO/IEC 17025:2017. Recorre organización, personal, instalaciones, equipos y metrología, materiales, muestras, integridad de datos, bioseguridad, residuos peligrosos y la certificación BPL del INVIMA.</p><h3>Objetivo general</h3><p>Que el Químico Farmacéutico implemente, mantenga y demuestre ante el INVIMA y el ONAC el cumplimiento de las Buenas Prácticas de Laboratorio en un laboratorio de control de calidad farmacéutico, asegurando resultados analíticos confiables, trazables y seguros.</p><h3>A quién va dirigido</h3><p>Químicos Farmacéuticos, jefes y analistas de control de calidad, profesionales de aseguramiento de calidad, auditores internos y estudiantes de último semestre de Química Farmacéutica en Colombia.</p><h3>Contexto normativo</h3><p>Colombia — normativa INVIMA / MinSalud</p>',
          'Calidad farmacéutica', 'intermedio', 'Que el Químico Farmacéutico implemente, mantenga y demuestre ante el INVIMA y el ONAC el cumplimiento de las Buenas Prácticas de Laboratorio en un laboratorio de control de calidad farmacéutico, asegurando resultados analíticos confiables, trazables y seguros.', 'Químicos Farmacéuticos, jefes y analistas de control de calidad, profesionales de aseguramiento de calidad, auditores internos y estudiantes de último semestre de Química Farmacéutica en Colombia.',
          1200, 'Edvanta', 'borrador', 'asincronica')
  RETURNING id INTO v_curso;

