  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.bfr.bund.de/cm/343/oecdgs97.pdf","title":"OECD Principles of Good Laboratory Practice (ENV/MC/CHEM(98)17)","description":"OCDE (copia BfR Alemania) (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.cba.gov.ar/wp-content/4p96humuzp/2012/07/sal_coeis_principiosbspr.pdf","title":"Principios de Buenas Prácticas de Laboratorio (versión en español)","description":"Gobierno de Córdoba, Argentina (ES)"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Comparativo: BPL control de calidad vs. BPL OCDE vs. ISO/IEC 17025 vs. BPM', 'Clase 3 · BPL OCDE, ISO/IEC 17025 y BPM: cómo se relacionan', 4, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Compara alcance, autoridad, obligatoriedad y enfoque de los cuatro marcos para decidir cuál aplica a cada laboratorio.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=JfzSOZ6i8io","provider":"youtube","videoId":"JfzSOZ6i8io","title":"ISO/IEC 17025:2017 Requisitos generales para competencia de los laboratorios de ensayo y calibración","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3619_2013.htm","title":"[Página web] Resolución 3619 de 2013 – Manual de BPL de control de calidad de productos farmacéuticos","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.paho.org/es/node/44617","title":"[Página web] Buenas prácticas de la OMS para laboratorios de control de calidad de productos farmacéuticos (TRS 957, Anexo 1)","description":"OPS/OMS (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: diferenciar con criterio los cuatro marcos que suelen confundirse en un laboratorio farmacéutico colombiano: BPL de control de calidad (Res. 3619 de 2013), BPL OCDE, ISO/IEC 17025:2017 y BPM.</p><p>Desarrollo: aunque comparten la sigla, las \"BPL\" de la Resolución 3619 de 2013 y los \"Principios BPL de la OCDE\" responden a preguntas distintas. La Resolución 3619 adopta en Colombia el Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos, basado en el Anexo 1 del Informe Técnico 957 de la OMS. Su alcance son los laboratorios que analizan materias primas, productos intermedios y terminados para liberar lotes o verificar su calidad: laboratorios de fabricantes, laboratorios externos contratados y laboratorios oficiales de control. La autoridad que verifica y certifica su cumplimiento es el INVIMA.</p><p>Los Principios BPL de la OCDE, en cambio, se aplican a estudios no clínicos de seguridad (toxicología, ecotoxicología, estudios en sistemas de prueba) cuyos datos se presentan a autoridades para registrar sustancias químicas, plaguicidas o medicamentos. Su lógica gira alrededor del \"estudio\": director de estudio, plan de estudio, unidad de garantía de calidad independiente, archivo de datos primarios e informe final. Su objetivo es la reconstrucción completa y la aceptación mutua de datos entre países.</p><p>La ISO/IEC 17025:2017 es una norma voluntaria de competencia técnica para cualquier laboratorio de ensayo o calibración, de cualquier sector. En Colombia la acreditación frente a ella la otorga el ONAC. Exige imparcialidad, validez de resultados, trazabilidad metrológica, estimación de la incertidumbre y un sistema de gestión, pero no es un requisito sanitario por sí misma.</p><p>Las BPM (Res. 1160 de 2016 y su marco) regulan la fabricación completa; el control de calidad es uno de sus capítulos, y la Res. 3619 profundiza en ese capítulo.</p><p>Ejemplo aplicado: un laboratorio farmacéutico de Bogotá que libera lotes de tabletas debe cumplir BPM y su laboratorio de control debe cumplir la Res. 3619 (certificable por INVIMA). Si además presta servicios analíticos a terceros, puede acreditarse en ISO/IEC 17025 ante ONAC para dar confianza adicional a sus clientes. Un centro de investigación que realiza estudios de toxicidad para un dossier internacional, en cambio, debería trabajar bajo los Principios BPL OCDE.</p><p>Puntos clave:<br>1. Res. 3619/2013 = control de calidad de productos farmacéuticos, obligatoria y certificada por INVIMA.<br>2. BPL OCDE = estudios no clínicos de seguridad, centrados en el estudio y su reconstrucción.<br>3. ISO/IEC 17025 = competencia técnica voluntaria, acreditada por ONAC; complementa pero no reemplaza a la Res. 3619.</p>"}'::jsonb);

