  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Diseño y distribución de áreas del laboratorio', 'Clase 2 · Instalaciones y condiciones ambientales', 1, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Describe los requisitos de separación de áreas, almacenamiento y servicios de apoyo de un laboratorio de control de calidad.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=Xo5J8l1Z5Gc","provider":"youtube","videoId":"Xo5J8l1Z5Gc","title":"BPL INF 57 OMS – 1er seminario","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3619_2013.htm","title":"[Página web] Resolución 3619 de 2013 – Manual de BPL de control de calidad de productos farmacéuticos","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.paho.org/es/documentos/documento-autoevaluacion-buenas-practicas-laboratorio-bpl","title":"[Página web] Documento de Autoevaluación de Buenas Prácticas de Laboratorio (BPL) – Red PARF Doc. Técnico 6","description":"OPS/OMS (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: describir los requisitos de diseño de instalaciones de un laboratorio de control de calidad farmacéutico según la Res. 3619 de 2013 (OMS TRS 957, Anexo 1).</p><p>Desarrollo: las instalaciones deben tener tamaño, construcción y ubicación adecuados para las actividades que se realizan y estar separadas de las áreas de producción. El diseño debe minimizar el riesgo de error y contaminación cruzada y facilitar la limpieza. Los principales requisitos son:</p><ul><li>Separación de áreas por tipo de actividad: recepción y almacenamiento de muestras, área fisicoquímica, área instrumental (HPLC, GC, espectrofotometría), área de balanzas protegida de corrientes y vibraciones, laboratorio de microbiología independiente, zona de lavado de material y zonas de oficina y archivo separadas de las áreas analíticas.</li><li>Áreas especiales para sustancias altamente tóxicas, radiactivas o para ensayos biológicos, con sistemas de extracción y acceso restringido.</li><li>Almacenamiento diferenciado y seguro para muestras (incluidas contramuestras), reactivos, sustancias de referencia y productos de control especial (en Colombia, sujetos al Fondo Nacional de Estupefacientes), con control de temperatura cuando aplique.</li><li>Servicios de apoyo: agua purificada con calidad definida, gases, energía estabilizada para instrumentos, duchas y lavaojos de emergencia, campanas de extracción.</li><li>Acceso controlado: solo personal autorizado ingresa a las áreas de laboratorio.</li></ul><p>Las superficies (pisos, paredes, mesones) deben ser lisas, resistentes a químicos y fáciles de limpiar. El laboratorio de microbiología requiere, además, flujo unidireccional de personal y materiales, y áreas con clasificación de aire cuando se realizan pruebas de esterilidad.</p><p>Ejemplo aplicado: un laboratorio externo en Medellín quiere certificarse en BPL ante INVIMA. En la autoevaluación detecta que la balanza analítica está junto a la campana de extracción y que las sustancias de referencia se guardan en la misma nevera que las muestras. El plan de mejora traslada la balanza a un cuarto con mesa antivibratoria y destina una nevera exclusiva, con control de acceso y registro continuo de temperatura, para sustancias de referencia.</p><p>Puntos clave:<br>1. El laboratorio debe estar separado de producción y dividido por tipo de actividad.<br>2. Muestras, reactivos, referencias y sustancias controladas requieren almacenamiento diferenciado y seguro.<br>3. Microbiología y sustancias peligrosas necesitan áreas independientes con controles específicos.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Monitoreo y control de condiciones ambientales', 'Clase 2 · Instalaciones y condiciones ambientales', 2, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica un programa de monitoreo de temperatura y humedad con límites, registros y gestión de excursiones.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=LwwKMfuN31I","provider":"youtube","videoId":"LwwKMfuN31I","title":"Interpretación ISO 17025 versión 2017 – 6.3 Instalaciones y condiciones ambientales","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3619_2013.htm","title":"[Página web] Resolución 3619 de 2013 – Manual de BPL de control de calidad de productos farmacéuticos","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: aplicar un programa de monitoreo de condiciones ambientales (temperatura, humedad relativa, iluminación, vibración) en el laboratorio de control de calidad.</p><p>Desarrollo: tanto la Res. 3619 de 2013 como la ISO/IEC 17025:2017 (numeral 6.3) exigen que las condiciones ambientales no invaliden los resultados. Esto implica tres pasos: definir, monitorear y reaccionar.</p><p>1. Definir: para cada área, identificar qué condiciones afectan los ensayos o equipos. Las balanzas y los equipos instrumentales suelen especificar rangos de temperatura y humedad; los métodos farmacopeicos pueden fijar temperaturas de ensayo (p. ej., disolución a 37 ± 0,5 °C); los reactivos, referencias y muestras tienen condiciones de almacenamiento definidas por el fabricante o la farmacopea (p. ej., 2–8 °C, 15–25 °C).<br>2. Monitorear: instalar termohigrómetros calibrados (con certificado trazable, idealmente de laboratorio acreditado por ONAC) o sistemas de registro continuo (data loggers) con alarmas. La frecuencia de registro debe ser coherente con el riesgo; para neveras y cuartos de estabilidad se prefiere registro continuo. Los registros deben cumplir ALCOA+: quien lee, cuándo, valor y firma.<br>3. Reaccionar: definir límites de alerta y de acción y un procedimiento para excursiones: qué hacer con las muestras o referencias afectadas, evaluación de impacto sobre los resultados emitidos, registro como desviación y, si aplica, CAPA.</p><p>También deben considerarse la iluminación adecuada para inspecciones visuales, el control de polvo y vibraciones en áreas de balanzas y el monitoreo microbiológico ambiental en microbiología.</p><p>Ejemplo aplicado: en un laboratorio de Cali, el data logger de la nevera de sustancias de referencia registró 11 °C durante 6 horas un fin de semana. El procedimiento indica cuarentena de las referencias, consulta de los datos de estabilidad del proveedor (USP o INVIMA), evaluación documentada y decisión del jefe de control de calidad. Como el certificado permitía excursiones cortas hasta 25 °C, se liberaron las referencias y se registró la desviación con su análisis de causa (falla eléctrica).</p><p>Puntos clave:<br>1. Cada área tiene condiciones ambientales definidas según el riesgo para ensayos, equipos y materiales.<br>2. El monitoreo usa instrumentos calibrados y registros íntegros, con alarmas cuando es crítico.<br>3. Toda excursión se gestiona como desviación con evaluación de impacto documentada.</p>"}'::jsonb);
