  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Recepción, registro, cadena de custodia y retención de muestras', 'Clase 3 · Manejo de muestras y emisión de resultados', 3, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica el flujo de recepción, codificación, almacenamiento, cadena de custodia y retención de muestras.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=rxXK8h7gFVw","provider":"youtube","videoId":"rxXK8h7gFVw","title":"Cadena de custodia digital para muestras (Laboratorios Norma 17025)","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3619_2013.htm","title":"[Página web] Resolución 3619 de 2013 – Manual de BPL de control de calidad de productos farmacéuticos","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: aplicar los requisitos de recepción, identificación, registro, almacenamiento y trazabilidad de muestras en el laboratorio de control de calidad.</p><p>Desarrollo: la Res. 3619 de 2013 (OMS TRS 957, Anexo 1, parte de muestras) exige que cada muestra que ingresa al laboratorio sea trazable desde su recepción hasta su disposición final. El flujo típico es:</p><p>1. Solicitud de análisis: documento que acompaña la muestra con nombre del producto, número de lote, fabricante, cantidad, fecha de muestreo, ensayos solicitados y especificación aplicable.<br>2. Recepción: verificación de integridad del envase, rotulado, cantidad suficiente (normalmente para análisis completo, repetición y contramuestra) y condiciones de transporte (p. ej., cadena de frío). Las no conformidades se registran y se comunican al solicitante.<br>3. Registro: asignación de un código único de laboratorio, ingreso al libro o sistema de registro de muestras (LIMS o equivalente) con fecha y hora.<br>4. Almacenamiento: en condiciones definidas, separado por estado (pendiente, en análisis, analizado), con acceso restringido. Las muestras de sustancias de control especial requieren custodia adicional.<br>5. Distribución al analista y cadena de custodia: cada transferencia queda registrada.<br>6. Retención y disposición: las contramuestras se conservan el tiempo definido (en industria, al menos un año después del vencimiento del lote, según BPM); al final se disponen como residuo según el plan de gestión.</p><p>Todo este flujo debe estar descrito en un procedimiento escrito, y el personal de recepción debe estar entrenado para rechazar o condicionar muestras que no cumplan, dejando constancia de la comunicación con el cliente o la autoridad.</p><p>Ejemplo aplicado: un laboratorio externo en Bogotá recibe del INVIMA (en un programa de vigilancia posmercado) una muestra de amoxicilina suspensión. El recepcionista verifica que vienen 6 frascos sellados, registra el código LAB-2026-0457, anota lote y fecha de vencimiento, y almacena en el área de muestras a 15–25 °C. Dos frascos se separan como contramuestra con rótulo de retención. Cada movimiento queda en el registro de cadena de custodia, que el INVIMA podrá revisar en una inspección.</p><p>Puntos clave:<br>1. Toda muestra llega con solicitud de análisis y recibe un código único de laboratorio.<br>2. La recepción verifica integridad, cantidad y condiciones, y registra no conformidades.<br>3. La cadena de custodia y la retención de contramuestras garantizan la trazabilidad completa.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Revisión, aprobación de resultados y certificado de análisis', 'Clase 3 · Manejo de muestras y emisión de resultados', 4, 'video')
