  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://combios.unizar.es/sites/combios/files/archivos/Legislacion/manual_bioseguridad_oms_2024_0.pdf","title":"Manual de bioseguridad en el laboratorio, 4.ª edición (OMS)","description":"OMS (copia Universidad de Zaragoza) (ES)"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Seguridad química: SGA, fichas de seguridad, almacenamiento y EPP', 'Clase 2 · Bioseguridad y seguridad química', 2, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica el SGA, las fichas de datos de seguridad, la compatibilidad de almacenamiento y la jerarquía de controles.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=kNTWTSf7ZAA","provider":"youtube","videoId":"kNTWTSf7ZAA","title":"Sistema Globalmente Armonizado (SGA): aprende a interpretar etiquetas y pictogramas químicos","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://ccs.org.co/wp-content/uploads/2023/01/RES0773SGA.pdf","title":"Resolución 0773 de 2021 – Aplicación del SGA en lugares de trabajo","description":"MinTrabajo y MinSalud (copia CCS) (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: aplicar medidas de seguridad química en el laboratorio: Sistema Globalmente Armonizado (SGA), fichas de datos de seguridad, almacenamiento compatible y elementos de protección personal.</p><p>Desarrollo: además del riesgo biológico, el laboratorio de control de calidad maneja solventes inflamables (metanol, acetonitrilo), ácidos y bases concentrados, oxidantes y sustancias tóxicas. Colombia adoptó el SGA para la clasificación y comunicación de peligros de productos químicos (Decreto 1496 de 2018), por lo que el laboratorio debe:</p><ul><li>Mantener un inventario de sustancias químicas con su clasificación de peligro.</li><li>Disponer de las fichas de datos de seguridad (FDS) de cada sustancia, en español y accesibles al personal.</li><li>Rotular todos los envases, incluidos los secundarios (soluciones preparadas), con identificación, pictogramas de peligro y fecha.</li><li>Almacenar según compatibilidad química: separar inflamables (en gabinetes para inflamables), ácidos de bases, oxidantes de orgánicos, y mantener cantidades mínimas en el área de trabajo.</li><li>Usar controles de ingeniería (campanas de extracción verificadas periódicamente) antes que EPP; y luego EPP adecuado: bata, gafas de seguridad, guantes compatibles con el químico, protección respiratoria cuando la evaluación de riesgo lo indique.</li><li>Tener duchas y lavaojos de emergencia verificados, kits para derrames y un plan de emergencias.</li><li>Capacitar al personal en estos riesgos, integrándolo al Sistema de Gestión de Seguridad y Salud en el Trabajo (Decreto 1072 de 2015).</li></ul><p>La seguridad química se conecta directamente con la gestión de residuos: los solventes agotados, las soluciones vencidas y los reactivos fuera de uso deben segregarse desde el punto de generación, rotularse y entregarse a gestores autorizados, tema que se profundiza en la siguiente clase.</p><p>Ejemplo aplicado: una auditoría interna en un laboratorio de Bogotá encuentra un frasco lavador con metanol sin rótulo y ácido nítrico almacenado junto a acetona. Se registra como hallazgo, se rotulan los envases secundarios según SGA y se reorganiza el almacén con una matriz de compatibilidad publicada en la puerta del gabinete.</p><p>Puntos clave:<br>1. Toda sustancia química debe tener FDS disponible y rótulo SGA, incluso en envases secundarios.<br>2. El almacenamiento se organiza por compatibilidad y con cantidades mínimas en mesones.<br>3. Primero controles de ingeniería, luego EPP, y siempre equipos de emergencia verificados.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Marco legal de residuos peligrosos: Decreto 4741/2005 y gestión de residuos en salud', 'Clase 3 · Gestión de residuos peligrosos del laboratorio', 3, 'video')
