  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Clasificación de no conformidades basada en riesgo', 'Clase 4 · Certificación BPL por el INVIMA', 6, 'manual')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica los criterios del INVIMA para clasificar no conformidades como críticas, mayores o menores.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Caso integrador: preparación para la visita de certificación', 'Clase 4 · Certificación BPL por el INVIMA', 7, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Ejecuta un plan de autoinspección, cierre de brechas y atención de la visita de certificación BPL del INVIMA.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=Xo5J8l1Z5Gc","provider":"youtube","videoId":"Xo5J8l1Z5Gc","title":"BPL INF 57 OMS – 1er seminario","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3619_2013.htm","title":"[Página web] Resolución 3619 de 2013 – Manual de BPL de control de calidad de productos farmacéuticos","description":"MinSalud / Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.paho.org/es/documentos/documento-autoevaluacion-buenas-practicas-laboratorio-bpl","title":"[Página web] Documento de Autoevaluación de Buenas Prácticas de Laboratorio (BPL) – Red PARF Doc. Técnico 6","description":"OPS/OMS (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: ejecutar un plan de preparación para una visita de certificación o seguimiento de BPL por parte del INVIMA.</p><p>Desarrollo: la certificación de BPL se basa en la verificación del cumplimiento de la Res. 3619 de 2013, usando la guía de evaluación (Anexo 2) y la guía de clasificación de no conformidades basada en riesgo (críticas, mayores y menores). Prepararse bien no es \"maquillar\" el laboratorio, sino demostrar que el sistema funciona todos los días. Un plan práctico incluye:</p><p>1. Autoinspección completa con la guía de evaluación del INVIMA, capítulo por capítulo (organización, documentación, personal, instalaciones, equipos, reactivos y referencias, muestras, métodos, resultados, seguridad).<br>2. Clasificación de las brechas encontradas con el mismo criterio de riesgo que usará el INVIMA y plan de acción con responsables y fechas; las brechas críticas y mayores se cierran antes de la visita.<br>3. Preparación documental: manual de calidad, listado maestro de documentos, organigrama y funciones, matriz de competencias, programa de calibración y mantenimiento con evidencias, inventario de sustancias de referencia, registros de condiciones ambientales, investigaciones OOS y desviaciones, CAPA y revisiones por la dirección.<br>4. Preparación del personal: simulacros de entrevista; cada analista debe poder explicar su procedimiento y mostrar sus registros. Designar un anfitrión y un \"cuarto de documentos\" para atender solicitudes de forma ordenada.<br>5. Durante la visita: responder con hechos y evidencias, no especular; registrar todo lo solicitado.<br>6. Después: analizar el acta, responder a los hallazgos dentro de los plazos con un plan CAPA concreto y verificable.</p><p>Ejemplo aplicado: un laboratorio externo en Bucaramanga solicita la certificación BPL. En la autoinspección encuentra que el 30 % de sus sustancias de referencia secundarias no tienen registro de calificación frente al estándar primario (posible no conformidad mayor). Prioriza su calificación, actualiza el procedimiento y entrena al personal. En la visita, el INVIMA solo registra dos no conformidades menores y el laboratorio obtiene la certificación tras presentar su plan de acción.</p><p>Puntos clave:<br>1. Use la guía de evaluación y la clasificación de riesgo del INVIMA para su autoinspección.<br>2. Cierre brechas críticas y mayores antes de la visita y tenga la evidencia organizada.<br>3. Después de la visita, responda con un plan CAPA concreto y dentro de los plazos.</p>"}'::jsonb);

END
$curso$;

-- ─── 6. Curso de Buenas Prácticas de Documentación Farmacéutica (30 clases) ───
DO $curso$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  -- Si ya está, no se duplica.
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Buenas Prácticas de Documentación Farmacéutica' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, level,
     objective, audience, duration_minutes, author_name, status, modality)
  VALUES ('edvanta', 'Curso de Buenas Prácticas de Documentación Farmacéutica', 'Curso práctico sobre Buenas Prácticas de Documentación (BPD/GDP) para químicos farmacéuticos en Colombia. Recorre la jerarquía documental, la redacción y el control de documentos, las reglas de diligenciamiento, los registros de lote y de laboratorio, la integridad de datos ALCOA+ y los registros electrónicos, con base en la normativa colombiana (Res. 1160 de 2016, Res.', '<p>Curso práctico sobre Buenas Prácticas de Documentación (BPD/GDP) para químicos farmacéuticos en Colombia. Recorre la jerarquía documental, la redacción y el control de documentos, las reglas de diligenciamiento, los registros de lote y de laboratorio, la integridad de datos ALCOA+ y los registros electrónicos, con base en la normativa colombiana (Res. 1160 de 2016, Res. 1403 de 2007, Ley 527 de 1999) y las guías OMS, PIC/S, FDA y UE.</p><h3>Objetivo general</h3><p>Que el estudiante diseñe, controle, diligencie y conserve documentos y registros farmacéuticos que cumplan las Buenas Prácticas de Documentación y los principios de integridad de datos exigidos por el INVIMA y los referentes internacionales.</p><h3>A quién va dirigido</h3><p>Químicos farmacéuticos, regentes de farmacia, profesionales de aseguramiento y control de calidad, producción y servicio farmacéutico, y estudiantes de últimos semestres de Química Farmacéutica en Colombia.</p><h3>Contexto normativo</h3><p>Colombia — normativa INVIMA / MinSalud</p>',
          'Calidad farmacéutica', 'intermedio', 'Que el estudiante diseñe, controle, diligencie y conserve documentos y registros farmacéuticos que cumplan las Buenas Prácticas de Documentación y los principios de integridad de datos exigidos por el INVIMA y los referentes internacionales.', 'Químicos farmacéuticos, regentes de farmacia, profesionales de aseguramiento y control de calidad, producción y servicio farmacéutico, y estudiantes de últimos semestres de Química Farmacéutica en Colombia.',
          1200, 'Edvanta', 'borrador', 'asincronica')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
