  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=4mCJaS5gzKI","provider":"youtube","videoId":"4mCJaS5gzKI","title":"What Are Good Documentation Practices (GDocP)? And Great Documentation Tips","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=55Oj5ghLC5o","provider":"youtube","videoId":"55Oj5ghLC5o","title":"Best Video on Good Documentation Practices - Documents and Records","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Normativa colombiana: Res. 1160 de 2016, Res. 1403 de 2007 e INVIMA', 'Clase 3 · Marco normativo de la documentación', 3, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Identifica los requisitos documentales que exigen las normas colombianas a fabricantes y servicios farmacéuticos y lo que verifica el INVIMA.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=w7H6ZO7mrCU","provider":"youtube","videoId":"w7H6ZO7mrCU","title":"Buenas prácticas de manufactura (BPM) según INVIMA en Colombia, mayo 2020","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm","title":"[Página web] Resolución 1160 de 2016 (MinSalud) - Manuales y guías de inspección de BPM (Anexo 1, sección 15 Documentación)","description":"Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.invima.gov.co/sites/default/files/resolucion_1403_2007.pdf","title":"Resolución 1403 de 2007 - Modelo de Gestión del Servicio Farmacéutico y Manual de Condiciones Esenciales y Procedimientos","description":"INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: identificar las normas colombianas que exigen un sistema documental en establecimientos farmacéuticos y reconocer qué espera el INVIMA encontrar durante una visita.</p><p>Desarrollo: en Colombia la documentación no es un requisito accesorio sino un componente central de las Buenas Prácticas de Manufactura (BPM). La Resolución 1160 de 2016 del Ministerio de Salud y Protección Social adopta los manuales de BPM (Anexo 1, principios fundamentales; Anexo 2, medicamentos estériles) y las guías de inspección basadas en los informes técnicos de la OMS (Informe 37, TRS 908, y su complemento del Informe 45, TRS 961), que el INVIMA aplica para otorgar el certificado de cumplimiento de BPM. Dentro del Anexo 1 existe un capítulo específico, la sección 15 \"Documentación\", que parte del principio de que \"una buena documentación es una parte esencial del sistema de garantía de calidad\" y exige: documentos diseñados, preparados, revisados y distribuidos con cuidado; aprobados, firmados y fechados por personas autorizadas; contenido inequívoco; revisión periódica; registros diligenciados en el momento en que se realiza cada acción; y correcciones que permitan leer el dato original. También exige especificaciones (materias primas, material de envase, producto terminado), fórmulas maestras, instrucciones de procesamiento y envasado, registros de lote, procedimientos y registros de recepción, muestreo, análisis, liberación, quejas, devoluciones, retiros del mercado y autoinspección.</p><p>Para el servicio farmacéutico (droguerías, farmacias-droguerías y servicios farmacéuticos hospitalarios), la Resolución 1403 de 2007 adopta el Modelo de Gestión del Servicio Farmacéutico y el Manual de Condiciones Esenciales y Procedimientos, que obliga a contar con procedimientos documentados para selección, adquisición, recepción, almacenamiento, dispensación, devoluciones, control de fechas de vencimiento y farmacovigilancia, además de los registros que evidencian su ejecución (por ejemplo, control de temperatura y humedad).</p><p>El INVIMA, como autoridad sanitaria nacional, verifica el cumplimiento durante las visitas de certificación y seguimiento usando las guías de inspección. En la práctica, gran parte de los hallazgos de una visita son documentales: POE desactualizados, registros incompletos, firmas faltantes o correcciones ilegibles. Por eso el QF debe conocer el capítulo de documentación tanto como el de producción o control de calidad.</p><p>Ejemplo aplicado: un laboratorio de sólidos orales en Bogotá recibe visita de seguimiento del INVIMA. El inspector solicita el registro de lote de un producto liberado hace tres meses y encuentra un espacio en blanco en la verificación de despeje de línea y una corrección con corrector líquido en el peso de un principio activo. Aunque el producto cumpla especificaciones, ambos hechos se registran como hallazgos porque no hay evidencia de que la actividad se haya hecho correctamente: lo que no está escrito no existe.</p><p>Puntos clave:<br>1. La Res. 1160 de 2016 incorpora un capítulo de documentación de cumplimiento obligatorio para fabricantes de medicamentos.<br>2. La Res. 1403 de 2007 exige procedimientos y registros documentados también en el servicio farmacéutico.<br>3. El INVIMA evalúa la documentación como evidencia objetiva de que las BPM se cumplen; un registro deficiente equivale a una actividad no demostrada.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
