  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=OeqRfDp_B90","provider":"youtube","videoId":"OeqRfDp_B90","title":"Buenas Prácticas de Documentación 1","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=osiPUaWV7NE","provider":"youtube","videoId":"osiPUaWV7NE","title":"Los secretos del control de documentos en ISO 9001","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Codificación y control de versiones', 'Clase 2 · Control de documentos', 1, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica un sistema de codificación y versionamiento que asegure la identificación única de cada documento.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=o0-nqa_fQKc","provider":"youtube","videoId":"o0-nqa_fQKc","title":"Control de documentos con base en la norma ISO 9001:2015","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm","title":"[Página web] Resolución 1160 de 2016 (MinSalud) - Manuales y guías de inspección de BPM (Anexo 1, sección 15 Documentación)","description":"Normograma INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: aplicar un sistema de codificación y versionamiento que garantice la identificación única de cada documento.</p><p>Desarrollo: el control de documentos empieza por asignar a cada documento un código único que permita identificar su tipo, el proceso al que pertenece y un consecutivo. Un esquema frecuente es TIPO-PROCESO-NÚMERO, por ejemplo: MC (manual de calidad), PO (procedimiento), IN (instructivo), FO (formato), ES (especificación), MM (método analítico). Así, \"PO-CC-015\" sería el procedimiento número 15 de Control de Calidad.</p><p>La versión indica el estado de revisión del documento. Se usa un número entero (00, 01, 02...) o letras. Cada vez que el contenido cambia de forma sustancial, la versión aumenta y se registra en el historial de cambios la descripción de lo modificado, el motivo y la referencia al control de cambios cuando aplique. La fecha de vigencia indica desde cuándo es obligatorio el documento, y la fecha de próxima revisión (normalmente cada dos o tres años) asegura que se revise aunque no haya cambios.</p><p>Los formatos heredan una relación con su POE: si cambia el formato, debe evaluarse si cambia el POE. Además, el encabezado y pie de página deben repetir código, versión y paginación \"página x de y\" para evitar el uso de hojas sueltas de versiones distintas.</p><p>Ejemplo aplicado: un laboratorio en Barranquilla tiene el procedimiento PO-PR-008 \"Despeje de línea\" versión 03. Tras una desviación se decide agregar la verificación por un segundo operario. Aseguramiento de calidad abre el control de cambios CC-2026-041, se emite la versión 04 con la descripción \"Se adiciona verificación independiente del despeje de línea (ref. CC-2026-041)\" y se actualiza el formato FO-PR-008-01 a versión 02. Ambos documentos se reemplazan en planta el mismo día después de capacitar al personal.</p><p>Buenas prácticas complementarias: no reutilizar nunca un código de un documento retirado, definir en el procedimiento de control documental qué se considera cambio menor (por ejemplo, un error tipográfico) y cómo se versiona, y bloquear la edición de los archivos vigentes para que solo aseguramiento de calidad pueda generar nuevas versiones. En sistemas electrónicos, el software asigna automáticamente el consecutivo y la versión, lo que reduce errores humanos.</p><p>Puntos clave:<br>1. Cada documento debe tener un código único, versión y fecha de vigencia visibles en todas sus páginas.<br>2. Todo cambio de versión se documenta en un historial con motivo y referencia.<br>3. Formatos y procedimientos deben actualizarse de manera coordinada.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Elaboración, revisión, aprobación, distribución y obsoletos', 'Clase 2 · Control de documentos', 2, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Interpreta el ciclo de vida de un documento controlado y los controles para evitar el uso de versiones obsoletas.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=fCyh4M7jz_4","provider":"youtube","videoId":"fCyh4M7jz_4","title":"Procedimiento de elaboración y control de documentos y registros bajo ISO 9001","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf","title":"Resolución 1160 de 2016","description":"Ministerio de Salud y Protección Social (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: interpretar el ciclo de vida de un documento controlado desde su elaboración hasta su retiro como obsoleto.</p><p>Desarrollo: el ciclo de vida documental tiene etapas definidas en el procedimiento de control de documentos:<br>1. Solicitud o necesidad: nace por un proceso nuevo, un cambio, una desviación, una CAPA o un hallazgo de auditoría.<br>2. Elaboración: el dueño del proceso redacta usando la plantilla oficial.<br>3. Revisión: un par técnico y aseguramiento de calidad verifican contenido, coherencia y cumplimiento normativo.<br>4. Aprobación: la persona autorizada (por ejemplo, el director técnico o jefe de aseguramiento) firma y fecha. Ningún documento se usa sin aprobación.<br>5. Capacitación: el personal involucrado se entrena antes de la fecha de vigencia y se deja registro.<br>6. Distribución controlada: se entregan copias identificadas (por ejemplo, sello \"Copia controlada No. 3\") a los puntos de uso, registrando quién las recibe. En sistemas electrónicos, el acceso se da por permisos de solo lectura.<br>7. Uso y revisión periódica.<br>8. Retiro y obsolescencia: al entrar una nueva versión se recogen todas las copias anteriores, se destruyen las copias de distribución y se conserva el original obsoleto, identificado con sello \"OBSOLETO\", durante el tiempo de retención definido.</p><p>El riesgo principal es el uso inadvertido de versiones obsoletas. Por eso la distribución debe ser trazable y las copias no controladas (fotocopias, impresiones locales) deben estar prohibidas o marcadas como \"Copia no controlada – solo informativa\".</p><p>Ejemplo aplicado: en una visita del INVIMA a un laboratorio de líquidos, el inspector encuentra en el área de envase el instructivo de la llenadora en versión 02, mientras que el listado maestro indica que la vigente es la 03. Se registra un hallazgo de control documental. La causa raíz: la distribución se hizo por correo y un supervisor imprimió la versión anterior. La CAPA incluye distribución solo desde el sistema y sello de copia controlada.</p><p>Puntos clave:<br>1. Ningún documento se usa sin estar revisado, aprobado, con capacitación y vigente.<br>2. La distribución debe ser controlada y trazable; las copias no controladas deben identificarse.<br>3. Los obsoletos se retiran de los puntos de uso, pero el original se archiva identificado.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Listado maestro de documentos', 'Clase 2 · Control de documentos', 3, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Ejecuta la construcción y actualización del listado maestro como herramienta de control y planeación.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=wHlMSNB3gos","provider":"youtube","videoId":"wHlMSNB3gos","title":"Listado Maestro de Documentos","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 2, '{"html":"<p>Objetivo: ejecutar la elaboración y mantenimiento del listado maestro de documentos.</p><p>Desarrollo: el listado maestro es el inventario oficial del sistema documental. Permite saber, en cualquier momento, qué documentos existen, cuál es su versión vigente y dónde están distribuidos. Sus campos mínimos son: código, título, tipo de documento, proceso o área, versión vigente, fecha de aprobación, fecha de vigencia, fecha de próxima revisión, responsable (dueño del proceso), ubicación de copias controladas, y estado (vigente, en revisión, obsoleto). También se recomienda incluir la relación entre POE y formatos asociados, y el tiempo de retención de los registros.</p><p>El listado maestro debe estar controlado: solo aseguramiento de calidad lo actualiza, se revisa con periodicidad definida y cada actualización deja trazabilidad (en Excel controlado, mediante versión y registro de cambios; en un sistema electrónico de gestión documental, mediante audit trail). Es también una herramienta de gestión: con filtros por fecha de próxima revisión se programa el plan anual de revisión documental, y con el campo de dueño se asignan responsabilidades.</p><p>Ejemplo aplicado: una distribuidora mayorista de medicamentos en Bogotá, preparando su certificación en Buenas Prácticas de Almacenamiento y Distribución, construye su listado maestro con 86 documentos. Al ordenarlo por fecha de próxima revisión descubre que 14 POE superaron los tres años sin revisión. El QF director técnico elabora un plan trimestral de revisión y, al presentarse la auditoría, puede demostrar control del sistema documental en minutos.</p><p>Al construirlo, se recomienda partir de un inventario físico de todos los documentos en uso en cada área, porque con frecuencia aparecen documentos que nunca pasaron por control (tablas pegadas en paredes, instructivos elaborados por el supervisor, formatos modificados a mano). Cada uno debe incorporarse formalmente al sistema o retirarse. También es útil agregar columnas de indicadores, como porcentaje de documentos revisados a tiempo, para presentar en la revisión por la dirección. Si el listado maestro se lleva en hoja de cálculo, el archivo debe protegerse contra edición, guardarse en una ubicación con respaldo y emitirse una versión aprobada cada vez que se actualice, de modo que siempre exista evidencia de cuál era el estado del sistema documental en una fecha dada.</p><p>Puntos clave:<br>1. El listado maestro identifica la versión vigente de todos los documentos y su ubicación.<br>2. Debe ser un documento controlado, actualizado únicamente por aseguramiento de calidad.<br>3. Sirve para planear las revisiones periódicas y demostrar control ante el INVIMA.</p>"}'::jsonb);
