  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=_4ZjdMD0YOY","provider":"youtube","videoId":"_4ZjdMD0YOY","title":"ALCOA+ Principles Explained in GMP","transcriptHtml":""}'::jsonb);
