  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Registros de lote de fabricación y envasado (BMR/BPR)', 'Clase 2 · Registros de lote y laboratorio', 1, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Interpreta el contenido de los registros de lote y los criterios de revisión antes de la liberación.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=9xh4pvDURHE","provider":"youtube","videoId":"9xh4pvDURHE","title":"Batch Record Review Process in Pharmaceutical Manufacturing. GMP Batch Release and Disposition","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=8MkPrCb0QbI","provider":"youtube","videoId":"8MkPrCb0QbI","title":"Secrets of Batch Manufacturing Records (BMR) Every Pharma Pro Must Know","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.gmp-compliance.org/files/guidemgr/chapter4_01-2011_en.pdf","title":"EU GMP Chapter 4: Documentation (2011)","description":"Comisión Europea (copia ECA Academy) (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: interpretar el contenido y la revisión de los registros de lote de fabricación (BMR) y de envasado (BPR).</p><p>Desarrollo: el registro de lote es la historia completa de cada lote producido; permite reconstruir qué se hizo, con qué materiales, en qué equipos, quién lo hizo y cuándo. Se emite a partir de la fórmula maestra y de las instrucciones de procesamiento y envasado aprobadas, como copia controlada y numerada asignada a un lote específico.</p><p>El registro de fabricación (BMR) incluye: nombre del producto y número de lote, fechas de inicio y fin de cada etapa, identificación de equipos y líneas, verificación de despeje de línea, materias primas con número de lote interno y cantidad pesada (con firma de quien pesa y quien verifica), parámetros de proceso (tiempos, temperaturas, velocidades), controles en proceso con resultados, rendimientos por etapa y conciliación, desviaciones ocurridas y firmas de cada operación. El registro de envasado (BPR) agrega: material de envase y empaque utilizado, muestras del material impreso codificado (lote y vencimiento), conciliación de material impreso, cantidad de producto terminado y controles de línea.</p><p>Antes de la liberación, producción revisa el registro y aseguramiento de calidad hace la revisión final: busca espacios en blanco, cálculos incorrectos, parámetros fuera de rango sin desviación, correcciones sin justificar y firmas faltantes. Solo con el registro completo y aprobado, junto con los resultados analíticos, el lote puede ser liberado.</p><p>Ejemplo aplicado: en la revisión del BMR del lote 26A045 de una tableta, el QF de aseguramiento detecta que el rendimiento de compresión fue 94 % cuando el rango aceptado es 97–101 %, sin desviación registrada. Detiene la liberación, solicita abrir la desviación, investigar la conciliación de granulado y dejar evidencia antes de decidir el destino del lote.</p><p>Diseño del registro de lote: los campos deben seguir el orden real del proceso, incluir rangos de aceptación impresos junto al espacio de diligenciamiento y prever espacio para observaciones y referencia a desviaciones. Los registros electrónicos de lote (EBR) automatizan verificaciones, impiden avanzar si falta un dato y reducen errores de cálculo, pero exigen validación del sistema y control de audit trail.</p><p>Puntos clave:<br>1. El registro de lote debe permitir reconstruir íntegramente la historia del lote.<br>2. Los pesajes y operaciones críticas requieren ejecutor y verificador.<br>3. Ningún lote se libera sin revisión completa del registro por aseguramiento de calidad.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Documentación de laboratorio de control de calidad', 'Clase 2 · Registros de lote y laboratorio', 2, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica las BPD a cuadernos, hojas de trabajo, bitácoras de equipos y datos cromatográficos.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=YE2VKv4S8YY","provider":"youtube","videoId":"YE2VKv4S8YY","title":"Webinar sobre Integridad de Datos en el Laboratorio","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=wYE1OCyfRgw","provider":"youtube","videoId":"wYE1OCyfRgw","title":"Chromatography Data Integrity in Pharma: Integration Rules, Reprocessing Control, Audit Trail Review","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://cdn.who.int/media/docs/default-source/medicines/norms-and-standards/guidelines/inspections/trs1033-annex4-guideline-on-data-integrity.pdf?sfvrsn=6218a4e6_4&download=true","title":"WHO TRS 1033 Annex 4 - Guideline on data integrity (PDF)","description":"OMS (WHO) (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: aplicar las buenas prácticas de documentación a cuadernos, bitácoras y registros analíticos del laboratorio de control de calidad.</p><p>Desarrollo: en el laboratorio se generan datos que sustentan la liberación de materias primas, productos en proceso y producto terminado. Por eso la documentación debe permitir reconstruir cada análisis. Elementos principales:<br>- Cuadernos o libretas de laboratorio controlados: con páginas numeradas, emitidos y registrados por aseguramiento de calidad, sin hojas arrancadas ni páginas en blanco sin anular.<br>- Hojas de trabajo analíticas: con referencia al método, número de muestra y lote, identificación de reactivos, estándares (lote, vencimiento, potencia), equipos utilizados con su estado de calibración, pesadas originales (preferiblemente impresas por la balanza), cálculos, resultados y comparación con la especificación.<br>- Bitácoras de uso de equipos: fecha, usuario, análisis realizado, observaciones.<br>- Registros de preparación de soluciones y reactivos.<br>- Datos cromatográficos y electrónicos: se considera dato original el archivo electrónico, no solo la impresión. Deben conservarse con su metadata y audit trail.<br>- Gestión de resultados fuera de especificación (OOS): ningún resultado se descarta sin investigación documentada.</p><p>La revisión por un segundo analista debe incluir los datos crudos, no solo el certificado de análisis.</p><p>Ejemplo aplicado: un analista de un laboratorio en Antioquia realiza valoración por HPLC. Integra manualmente un pico sin justificación y no deja registro. En la revisión, el supervisor consulta el audit trail del software, encuentra la reintegración y exige justificar o reprocesar según el POE de integración cromatográfica. Este control evita un hallazgo de integridad de datos en la siguiente visita del INVIMA.</p><p>Además, el laboratorio debe controlar la emisión de formatos en blanco: las hojas de trabajo se entregan numeradas y se concilian, para impedir que un analista repita un análisis en una hoja nueva y descarte la original sin dejar evidencia (práctica conocida como testing into compliance). Los estándares de referencia, reactivos y soluciones deben estar rotulados con identificación, fecha de preparación, vencimiento y responsable, y su preparación debe ser trazable al registro correspondiente.</p><p>Puntos clave:<br>1. Cada análisis debe ser reconstruible a partir de sus datos crudos y registros.<br>2. Los cuadernos y hojas de trabajo deben estar controlados y numerados.<br>3. En sistemas computarizados, el dato original es el electrónico, con su audit trail.</p>"}'::jsonb);
