  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Introducción a la unidad: del auditor individual al programa de auditoría', 'Clase 1 · Introducción a la unidad', 0, 'video')
