  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Resume por qué una organización necesita gestionar sus auditorías como un programa y qué competencias debe tener quien audita.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=I0FhyYAtgU0","provider":"youtube","videoId":"I0FhyYAtgU0","title":"El programa de auditoría según la norma ISO 19011","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=fsNrrApdugw","provider":"youtube","videoId":"fsNrrApdugw","title":"Gestión de un programa de auditoría ISO 19011:2018 – Curso de auditoría","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: Resumir el enfoque de ISO 19011:2018 sobre la gestión del programa de auditoría y la competencia de los auditores, y su importancia para empresas farmacéuticas colombianas.</p><p>Desarrollo: Una auditoría aislada sirve de poco si no responde a un plan coherente. ISO 19011:2018 dedica su capítulo 5 a la gestión del programa de auditoría y su capítulo 7 a la competencia y evaluación de los auditores. El programa define qué se audita, con qué frecuencia, con qué recursos, quién lo hace y cómo se evalúa si el propio programa funciona. Sigue el ciclo Planificar–Hacer–Verificar–Actuar: se establecen objetivos, se determinan y evalúan riesgos y oportunidades del programa, se establece el programa, se implementa, se hace seguimiento y se revisa y mejora.</p><p>En la industria farmacéutica el programa de auditoría suele incluir tres grandes bloques: autoinspecciones BPM/BPL por áreas o capítulos, auditorías a proveedores y fabricantes por contrato, y auditorías al sistema de gestión (por ejemplo ISO 9001). Las BPM exigen que la autoinspección sea periódica y que cubra todos los aspectos de producción y control de calidad; las buenas prácticas también exigen que los proveedores críticos estén calificados, lo que normalmente implica auditorías. Un programa bien diseñado reparte esfuerzos según riesgo: un proveedor de principio activo estéril no se audita con la misma frecuencia que uno de cajas plegadizas.</p><p>La segunda mitad de la unidad se centra en las personas. Un auditor farmacéutico necesita conocimientos genéricos de auditoría (principios, métodos, técnicas de muestreo), conocimientos específicos del sector (BPM, BPL, servicio farmacéutico, integridad de datos, validación) y comportamientos personales como ética, diplomacia, observación, perseverancia y apertura mental. La organización debe definir criterios de competencia, evaluar a sus auditores y mantener y mejorar esa competencia.</p><p>Ejemplo aplicado: Un laboratorio mediano en Barranquilla tenía a una sola persona, el jefe de aseguramiento, realizando todas las autoinspecciones, sin calendario ni criterios. Al rediseñar su programa con base en ISO 19011, formó un equipo de cinco auditores internos de distintas áreas, definió un calendario anual basado en riesgo, separó funciones para garantizar independencia e incorporó indicadores para evaluar el programa.</p><p>Puntos clave:<br>1. El programa de auditoría convierte auditorías sueltas en un sistema gestionado con ciclo PHVA.<br>2. El riesgo determina alcance, frecuencia y profundidad de cada auditoría del programa.<br>3. La competencia del auditor se define, se evalúa y se mantiene; no se presume.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Establecer objetivos, alcance y recursos del programa de auditoría', 'Clase 2 · Gestión del programa de auditoría', 1, 'video')
