  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Describe los conocimientos, habilidades y comportamientos que debe tener un auditor farmacéutico y cómo se evalúan.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=Uymfz0ojbKw","provider":"youtube","videoId":"Uymfz0ojbKw","title":"ISO 19011:2018 Requisito 7. Competencia y evaluación de los auditores","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=SXbR3vSx4is","provider":"youtube","videoId":"SXbR3vSx4is","title":"Competencias del auditor líder y auditores internos ISO 9001:2015 e ISO 19011:2018","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: Describir las competencias requeridas para un auditor de calidad farmacéutica y los métodos para evaluarlas y mantenerlas, según el capítulo 7 de ISO 19011:2018.</p><p>Desarrollo: ISO 19011 define la competencia como la capacidad de aplicar conocimientos y habilidades para lograr los resultados previstos. Para un auditor distingue:<br>- Comportamiento personal: ético, de mentalidad abierta, diplomático, observador, perceptivo, versátil, tenaz, decidido, seguro de sí mismo, capaz de actuar con fortaleza, abierto a la mejora, culturalmente sensible y colaborador.<br>- Conocimientos y habilidades genéricos: principios, procesos y métodos de auditoría; normas de sistemas de gestión y documentos de referencia; contexto de la organización; requisitos legales y reglamentarios aplicables.<br>- Conocimientos específicos de la disciplina y del sector: en farmacéutica, BPM, BPL, validación de procesos y métodos, sistemas de agua y aire, integridad de datos, cadena de frío, farmacovigilancia y servicio farmacéutico, según el alcance.<br>- Competencias del líder del equipo: planificar, organizar, dirigir el equipo, representarlo frente al auditado, resolver conflictos y preparar y completar el informe.</p><p>La organización debe establecer criterios de evaluación (por ejemplo, profesión de QF o afín, experiencia mínima en planta o laboratorio, formación como auditor interno de 16 a 40 horas, participación en un número mínimo de auditorías como observador) y aplicar métodos de evaluación: revisión de registros de formación y experiencia, retroalimentación de auditados, entrevistas, observación del auditor en campo y revisión posterior de sus informes. La competencia se mantiene con desarrollo profesional continuo, práctica regular y actualización normativa, algo crítico en Colombia, donde la regulación sanitaria se actualiza con frecuencia.</p><p>Ejemplo aplicado: Un laboratorio define tres niveles: auditor en formación (curso de 24 horas, dos auditorías como observador), auditor interno (al menos cuatro auditorías supervisadas con evaluación satisfactoria) y auditor líder (más de diez auditorías, formación en liderazgo y aprobación del jefe de aseguramiento). Cada año, el responsable del programa observa una auditoría de cada auditor con un formato de evaluación de diez criterios.</p><p>Puntos clave:<br>1. La competencia del auditor combina comportamiento, conocimiento genérico y conocimiento específico del sector.<br>2. Los criterios de competencia deben estar documentados y ser evaluables.<br>3. La evaluación es continua: formación, observación en campo y retroalimentación.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Ética, comunicación y comportamiento del auditor en campo', 'Clase 3 · Competencias del auditor', 4, 'video')
