  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Introducción a la unidad: el ciclo de una auditoría individual', 'Clase 1 · Introducción a la unidad', 0, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Resume las etapas de una auditoría según el capítulo 6 de ISO 19011, desde el inicio hasta la recolección de evidencia en sitio.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=tVjJ8It3pL0","provider":"youtube","videoId":"tVjJ8It3pL0","title":"Curso intensivo de auditores internos ISO 19011 – Módulo 3: Conducción de la auditoría","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=85hSWGF-v0I","provider":"youtube","videoId":"85hSWGF-v0I","title":"ISO 19011: Realización y resolución de la auditoría","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: Resumir las etapas de una auditoría individual según el capítulo 6 de ISO 19011:2018 y ubicar en ellas las actividades propias de una auditoría farmacéutica.</p><p>Desarrollo: El capítulo 6 de ISO 19011 describe la realización de una auditoría en seis etapas: (1) inicio de la auditoría, (2) preparación de las actividades, (3) realización de las actividades, (4) preparación y distribución del informe, (5) finalización y (6) realización de las acciones de seguimiento, cuando se especifican. Esta unidad cubre las tres primeras; la Unidad 4 cubre las siguientes.</p><p>El inicio incluye el contacto con el auditado y la determinación de la viabilidad: ¿hay información suficiente?, ¿colaborará el auditado?, ¿hay tiempo y recursos? La preparación incluye la revisión de información documentada (manual de calidad, listado maestro de procedimientos, resultados de auditorías anteriores, quejas, desviaciones, registros de producto), la planificación basada en riesgo, la asignación de tareas al equipo y la preparación de la información documentada de trabajo: listas de verificación, formularios de muestreo y formatos de registro de evidencia.</p><p>La realización en sitio incluye la reunión de apertura, la revisión de documentos durante la auditoría, la comunicación durante la auditoría, la asignación de roles a guías y observadores, la recolección y verificación de información, la generación de hallazgos, la determinación de conclusiones y la reunión de cierre. En farmacéutica, la recolección de información incluye un componente físico muy importante: el recorrido por la planta, el almacén o el laboratorio, siguiendo el flujo de materiales y personas.</p><p>La unidad también aborda dos variantes cada vez más frecuentes: la auditoría a proveedores y fabricantes por contrato, que tiene particularidades contractuales y técnicas, y la auditoría remota, consolidada desde la pandemia de COVID-19 tanto por la industria como por autoridades sanitarias.</p><p>Ejemplo aplicado: Para auditar el área de control de calidad microbiológico de una planta en Valle del Cauca, el auditor líder revisa primero los resultados de la autoinspección anterior, las tendencias de monitoreo ambiental y dos investigaciones fuera de especificación del semestre. Con eso define un plan de un día, una lista de verificación basada en la Res. 3619/2013 y una muestra de registros a revisar.</p><p>Puntos clave:<br>1. ISO 19011 organiza la auditoría en seis etapas; la preparación determina la calidad de la ejecución.<br>2. La revisión documental previa permite enfocar la auditoría en riesgos reales.<br>3. En farmacéutica, la evidencia física del recorrido es tan importante como la documental.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Elaboración del plan de auditoría', 'Clase 2 · Planificación de la auditoría', 1, 'video')
  RETURNING id INTO v_clase;
