  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica una auditoría por procesos al servicio farmacéutico de una IPS, desde la selección hasta la dispensación y la farmacovigilancia.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=tLsUIOW8xNw","provider":"youtube","videoId":"tLsUIOW8xNw","title":"Módulo 4 – Auditoría de Farmacia","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=lPJsjc2o9h4","provider":"youtube","videoId":"lPJsjc2o9h4","title":"Recepción resolución 1403","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.invima.gov.co/sites/default/files/resolucion_1403_2007.pdf","title":"Resolución 1403 de 2007 – Modelo de Gestión del Servicio Farmacéutico y Manual de Condiciones Esenciales y Procedimientos","description":"Ministerio de la Protección Social / INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: Aplicar una auditoría por procesos al servicio farmacéutico de una IPS, utilizando la Resolución 1403 de 2007 como criterio principal.</p><p>Desarrollo: El servicio farmacéutico hospitalario es un sistema de procesos que impacta directamente la seguridad del paciente. Una auditoría eficaz sigue el ciclo del medicamento dentro de la institución:<br>1. Selección: existencia y funcionamiento del comité de farmacia y terapéutica, actas, listado básico de medicamentos y criterios de inclusión.<br>2. Adquisición: proveedores evaluados y autorizados, verificación de registro sanitario vigente y de la condición de proveedor autorizado.<br>3. Recepción técnica y administrativa: verificación de lote, fecha de vencimiento, registro sanitario, condiciones de transporte y cadena de frío; manejo de no conformidades de recepción.<br>4. Almacenamiento: condiciones de temperatura y humedad registradas, sistema de rotación (primero en vencer, primero en salir), separación de productos de alto riesgo y de nombres o empaques similares, control de vencidos y medicamentos de control especial bajo custodia.<br>5. Distribución y dispensación: sistema de distribución de medicamentos en dosis unitaria o equivalente, validación de la prescripción por el QF, conciliación medicamentosa, información al paciente.<br>6. Preparaciones o adecuaciones: si la IPS realiza mezclas parenterales, reempaque o reenvase, verificar las condiciones exigidas y la certificación correspondiente.<br>7. Devoluciones y destrucción: trazabilidad de devoluciones y actas de destrucción conforme a la normativa ambiental y sanitaria.<br>8. Farmacovigilancia y seguridad del paciente: programa institucional, reporte de eventos adversos y errores de medicación, análisis y acciones.<br>9. Sistema de gestión de calidad del servicio: procedimientos, indicadores, auditorías internas y capacitación.</p><p>Técnicas específicas: rastrear una prescripción real desde la orden médica hasta la administración al paciente; hacer un conteo físico de una muestra de medicamentos de control especial y compararlo con el registro; revisar el registrador de temperatura de una nevera en los últimos 30 días; observar una dispensación completa.</p><p>Ejemplo aplicado: En una clínica de Cartagena, la auditora selecciona aleatoriamente cinco pacientes hospitalizados. Rastrea sus prescripciones y encuentra que en dos casos el medicamento de alto riesgo (heparina) se dispensó sin doble verificación, aunque el procedimiento institucional la exige. En el inventario de control especial, el conteo de un opioide difiere en una unidad del libro oficial. Registra dos no conformidades, la segunda clasificada como mayor por su implicación regulatoria.</p><p>Puntos clave:<br>1. Auditar siguiendo el ciclo del medicamento dentro de la IPS.<br>2. Rastreo de pacientes y conteos físicos son técnicas de alto rendimiento.<br>3. Medicamentos de alto riesgo y de control especial merecen siempre muestreo dirigido.</p>"}'::jsonb);
