  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=mFq8WrponIU","provider":"youtube","videoId":"mFq8WrponIU","title":"¿Cómo aplicar el DIAGRAMA DE ISHIKAWA? Concepto, pautas y elaboración del Diagrama Causal","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=7P3ePhzi6A4","provider":"youtube","videoId":"7P3ePhzi6A4","title":"Ishikawa en Salud","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 3, '{"source":"enlace","url":"https://www.youtube.com/watch?v=SXqsXVn_SO0","provider":"youtube","videoId":"SXqsXVn_SO0","title":"¿Qué es un Diagrama Ishikawa, Causa efecto o Espina de pescado? Ejemplos","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: construir diagramas de flujo e Ishikawa como herramientas de identificación de peligros y de análisis de causas.</p><p>Desarrollo:<br>Diagrama de flujo: representa la secuencia de etapas de un proceso: entradas, operaciones, controles en proceso, puntos de decisión y salidas. En QRM es el punto de partida casi obligatorio, porque garantiza que el equipo no olvide etapas al buscar peligros. Recomendaciones: elaborarlo con el personal que ejecuta el proceso, verificarlo en planta (\"caminar el proceso\") e incluir las transferencias entre áreas, que suelen concentrar errores.</p><p>Diagrama de Ishikawa (causa-efecto o espina de pescado): ubica el efecto o problema en la \"cabeza\" y organiza las causas potenciales en ramas. En la industria farmacéutica se usan habitualmente las 6M:<br>- Mano de obra (personal): capacitación, fatiga, rotación.<br>- Máquina (equipos): calibración, desgaste, mantenimiento.<br>- Método: procedimientos, parámetros, instrucciones de fabricación.<br>- Material: materias primas, material de envase, variabilidad del proveedor.<br>- Medición: métodos analíticos, instrumentos, muestreo.<br>- Medio ambiente: temperatura, humedad, presiones diferenciales, limpieza de áreas.</p><p>Pasos para construirlo:<br>1. Definir el efecto de forma específica y medible (por ejemplo, \"dureza de tabletas por debajo de 6 kp en el lote L-2045\").<br>2. Dibujar las ramas principales.<br>3. Generar causas en cada rama mediante lluvia de ideas y la técnica de los \"5 por qué\".<br>4. Depurar y priorizar las causas más probables con datos.<br>5. Verificar las causas prioritarias con evidencia (registros de lote, datos de equipo, análisis).</p><p>Limitaciones: el Ishikawa no estima la probabilidad ni la severidad. Es una herramienta de identificación y organización, por lo que suele combinarse con el AMEF o con una matriz de riesgo. No es un análisis de riesgos completo por sí mismo.</p><p>Ejemplo aplicado: un laboratorio en Barranquilla recibe quejas por tabletas de metformina que se fragmentan. El equipo dibuja el diagrama de flujo (dispensación, granulación húmeda, secado, tamizado, mezcla final, compresión, recubrimiento, empaque) y luego un Ishikawa sobre el efecto \"tabletas friables\". Causas identificadas:<br>- Material: cambio de lote del aglutinante.<br>- Método: tiempo de secado reducido.<br>- Máquina: punzones desgastados.<br>- Medio ambiente: humedad relativa alta en la sala de compresión durante la temporada de lluvias.<br>- Medición: durómetro con calibración vencida.<br>Los datos confirman que la humedad de los gránulos estuvo en el límite superior. La investigación y su CAPA se gestionan en los procesos correspondientes, y la evaluación de riesgos se actualiza.</p><p>Puntos clave:<br>1. El diagrama de flujo asegura que se revisen todas las etapas del proceso.<br>2. El Ishikawa organiza las causas potenciales con las 6M, pero no cuantifica el riesgo.<br>3. Las causas identificadas deben verificarse con datos antes de concluir.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Análisis Preliminar de Peligros (PHA)', 'Clase 2 · Herramientas básicas y de priorización', 2, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>El estudiante aplica el PHA para identificar y clasificar peligros en etapas tempranas de un proyecto, cuando la información es limitada.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=jfuDY3IRpkE","provider":"youtube","videoId":"jfuDY3IRpkE","title":"¿Cómo hacer una matriz de riesgo de probabilidad por impacto? por Héctor Muskus","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.farmaceuticos.com/wp-content/uploads/2021/05/2018-Gestion-riegos-calidad-industria-farmaceutica.pdf","title":"ICH Q9 Gestión de Riesgos de Calidad (QRM): definiciones, proceso y herramientas (AMFE, FTA, APPCC, HAZOP, PHA)","description":"AEFI Sección Catalana (alojado en farmaceuticos.com) (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: aplicar el Análisis Preliminar de Peligros (Preliminary Hazard Analysis, PHA) en situaciones de baja información y alta incertidumbre.</p><p>Desarrollo: el PHA se basa en aplicar la experiencia o el conocimiento previo de un peligro o falla para identificar peligros, situaciones peligrosas y eventos futuros que podrían causar daño. Además, estima su probabilidad de ocurrencia para una actividad, instalación, producto o sistema determinado. Según ICH Q9(R1), es útil para analizar sistemas existentes o priorizar peligros cuando las circunstancias impiden aplicar una técnica más extensa, y se usa con frecuencia en el diseño de productos, procesos e instalaciones.</p><p>Pasos típicos:<br>1. Identificar las posibilidades de que ocurra el evento de riesgo.<br>2. Evaluar cualitativamente el daño o la enfermedad que podría resultar.<br>3. Clasificar el riesgo combinando severidad y probabilidad, normalmente en una matriz de riesgo.<br>4. Identificar posibles medidas correctivas o preventivas.</p><p>Formato habitual de una tabla PHA: peligro, causa, consecuencia, severidad (por ejemplo, de 1 a 4), probabilidad (de 1 a 4), nivel de riesgo (bajo, medio, alto o crítico) y medidas propuestas.</p><p>Ventajas: es rápido, se aplica con poca información y genera un inventario temprano de peligros que luego puede profundizarse con AMEF o HACCP.<br>Limitaciones: es cualitativo y depende mucho de la experiencia del equipo. No sustituye un análisis detallado cuando el proyecto avanza.</p><p>Aplicaciones farmacéuticas:<br>- Diseño conceptual de una nueva planta o área.<br>- Evaluación inicial de la incorporación de un producto nuevo a instalaciones existentes.<br>- Selección preliminar de proveedores en un país nuevo.<br>- Fase temprana de desarrollo de una formulación.</p><p>Ejemplo aplicado: una empresa colombiana planea construir un área de fabricación de cremas y ungüentos en Rionegro. En la etapa de diseño conceptual se realiza un PHA:<br>- Peligro \"contaminación microbiana por agua de calidad inadecuada\": severidad 3, probabilidad 3, riesgo alto. Medida: sistema de agua purificada con lazo de recirculación y sanitización.<br>- Peligro \"mezcla de productos por flujos cruzados de personal\": severidad 3, probabilidad 2, riesgo medio. Medida: diseño con flujos unidireccionales y esclusas.<br>- Peligro \"temperatura excesiva que degrada el activo termolábil\": severidad 2, probabilidad 2, riesgo medio. Medida: climatización con monitoreo.<br>El PHA alimenta los requisitos de usuario (URS) y se profundizará con un AMEF cuando el diseño de detalle esté disponible.</p><p>Puntos clave:<br>1. El PHA identifica y clasifica peligros de forma temprana y con poca información.<br>2. Suele combinarse con una matriz de severidad × probabilidad.<br>3. Es un punto de partida; los riesgos altos se analizan después con herramientas más detalladas.</p>"}'::jsonb);
