  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>El estudiante aplica matrices de probabilidad × severidad y la técnica de ranking y filtrado para priorizar riesgos y asignar recursos.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=k1aD1q9HEAo","provider":"youtube","videoId":"k1aD1q9HEAo","title":"Matrices de Riesgo, cómo elaborarlas: Impacto y Probabilidad","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=BsNHSIcLhYE","provider":"youtube","videoId":"BsNHSIcLhYE","title":"¿Cómo realizar una matriz de riesgos (Probabilidad e Impacto) para un proyecto?","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.farmaceuticos.com/wp-content/uploads/2021/05/2018-Gestion-riegos-calidad-industria-farmaceutica.pdf","title":"ICH Q9 Gestión de Riesgos de Calidad (QRM): definiciones, proceso y herramientas (AMFE, FTA, APPCC, HAZOP, PHA)","description":"AEFI Sección Catalana (alojado en farmaceuticos.com) (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: aplicar matrices de riesgo y la técnica de ranking y filtrado para comparar y priorizar riesgos de manera transparente.</p><p>Desarrollo:<br>Matriz de riesgo: tabla de doble entrada con la severidad en un eje y la probabilidad en el otro (habitualmente 3×3, 4×4 o 5×5). Cada celda se asigna a un nivel de riesgo, por ejemplo bajo (verde), medio (amarillo) o alto (rojo), con una acción asociada: aceptar, controlar o actuar de inmediato. Buenas prácticas:<br>- Definir descriptores concretos para cada nivel. Severidad 5 puede significar \"daño grave o muerte del paciente\"; probabilidad 1 puede significar \"no se ha presentado en la industria\".<br>- Hacer la matriz asimétrica a favor de la severidad: una severidad catastrófica no debería quedar en verde aunque la probabilidad sea baja.<br>- Recordar que las celdas son ordinales: un \"12\" no es exactamente el doble de un \"6\".</p><p>Ranking y filtrado de riesgos (risk ranking and filtering): herramienta de ICH Q9(R1) para comparar y priorizar riesgos. Suele descomponer la pregunta de riesgo en tantos componentes como sea necesario para capturar los factores que intervienen. Esos factores se combinan en una puntuación relativa (con pesos), y luego se aplican \"filtros\", es decir, umbrales para seleccionar qué riesgos se gestionan o estudian primero.</p><p>Aplicaciones:<br>- Priorizar instalaciones o proveedores para auditoría o inspección.<br>- Decidir la frecuencia de recalificación de equipos.<br>- Priorizar productos para la revisión periódica o para validaciones retrospectivas.<br>- En las autoridades: priorizar sitios de fabricación para inspección, un enfoque que el INVIMA utiliza en su planificación.</p><p>Pasos:<br>1. Definir los factores de riesgo (por ejemplo, para proveedores: criticidad del material, historial de calidad, resultados de auditorías previas, complejidad del proceso, país de origen).<br>2. Definir escalas y pesos.<br>3. Puntuar cada elemento.<br>4. Calcular la puntuación total y ordenar.<br>5. Aplicar filtros: por ejemplo, \"auditoría presencial anual si la puntuación es mayor de 70; cuestionario si está entre 40 y 70; revisión documental si es menor de 40\".</p><p>Ejemplo aplicado: un laboratorio de Bogotá con 45 proveedores necesita priorizar su plan anual de auditorías con recursos limitados. Construye un ranking con cinco factores: criticidad del material (peso 35 %), historial de no conformidades (25 %), último resultado de auditoría (20 %), complejidad del proceso del proveedor (10 %) y cambios recientes notificados (10 %). El proveedor de principio activo estéril obtiene 88 y queda para auditoría presencial; el proveedor de cajas plegadizas obtiene 32 y se gestiona con revisión documental. La metodología queda documentada en el procedimiento de calificación de proveedores.</p><p>Puntos clave:<br>1. La matriz de riesgo debe tener descriptores claros y no subestimar las severidades altas.<br>2. El ranking y filtrado prioriza muchos elementos con factores ponderados y umbrales definidos.<br>3. Ambas herramientas facilitan una asignación de recursos proporcional al riesgo.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'AMEF/FMEA paso a paso: severidad, ocurrencia, detección y NPR', 'Clase 3 · Herramientas formales avanzadas', 4, 'video')
