  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=gpDj6QBtKtY","provider":"youtube","videoId":"gpDj6QBtKtY","title":"¿Qué es HACCP? Los 7 Principios de HACCP Explicados","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=B0lmBK42d5o","provider":"youtube","videoId":"B0lmBK42d5o","title":"Los 7 principios del APPCC","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.gmp-navigator.com/files/guidemgr/WHO_TRS_908_Annex7.pdf","title":"Annex 7: Application of HACCP methodology to pharmaceuticals (WHO TRS 908, 2003)","description":"OMS / WHO (alojado por GMP-Navigator) (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: aplicar los siete principios del Análisis de Peligros y Puntos Críticos de Control (HACCP o APPCC) a un proceso farmacéutico.</p><p>Desarrollo: el HACCP nació en la industria de alimentos y la OMS lo adaptó al sector farmacéutico. La OMS publicó una guía de aplicación de HACCP a productos farmacéuticos en sus informes técnicos, y ICH Q9(R1) lo incluye en su Anexo I como una herramienta sistemática, proactiva y preventiva para asegurar la calidad, la confiabilidad y la seguridad. Es especialmente útil cuando se comprenden bien el proceso y el producto, y para identificar y gestionar riesgos asociados a peligros físicos, químicos y biológicos, incluida la contaminación microbiológica.</p><p>Los siete principios:<br>1. Realizar un análisis de peligros e identificar medidas preventivas para cada etapa del proceso.<br>2. Determinar los puntos críticos de control (PCC). Un PCC es la etapa donde un control es esencial para prevenir o eliminar un peligro, o reducirlo a un nivel aceptable. Suele usarse un árbol de decisión.<br>3. Establecer límites críticos para cada PCC.<br>4. Establecer un sistema de monitoreo de los PCC.<br>5. Establecer las acciones correctivas que se tomarán cuando el monitoreo indique que un PCC no está bajo control.<br>6. Establecer procedimientos de verificación de que el sistema HACCP funciona eficazmente.<br>7. Establecer la documentación de todos los procedimientos y registros.</p><p>Pasos previos: formar el equipo, describir el producto y su uso previsto, elaborar el diagrama de flujo y verificarlo en planta.</p><p>Diferencias con el AMEF: el AMEF prioriza modos de falla con puntuaciones; el HACCP se centra en controlar peligros en puntos específicos con límites medibles y monitoreo continuo. En la práctica se complementan: el AMEF puede ayudar a identificar dónde están los PCC.</p><p>Ejemplo aplicado: un laboratorio en Bogotá que fabrica soluciones orales no estériles aplica HACCP con foco en la contaminación microbiológica.<br>- Etapa: obtención de agua purificada. Peligro: crecimiento microbiano. PCC: sí. Límite crítico: conteo microbiano por debajo del límite de alerta interno y conductividad dentro de especificación. Monitoreo: conductividad en línea continua y microbiología según el plan. Acción correctiva: detener el uso, sanitizar e investigar. Verificación: tendencias mensuales.<br>- Etapa: preparación y calentamiento. Peligro: supervivencia de microorganismos. Límite crítico: temperatura y tiempo definidos en la validación. Monitoreo: registrador de temperatura.<br>- Etapa: almacenamiento del granel. Peligro: proliferación microbiana. Límite crítico: tiempo máximo de espera validado (por ejemplo, 72 horas). Monitoreo: registro de hora de fabricación y de llenado.<br>- Etapa: llenado. Peligro: contaminación por el ambiente. PCC según el análisis. Control: limpieza y sanitización de la llenadora, y monitoreo ambiental.</p><p>Puntos clave:<br>1. El HACCP es preventivo y se basa en siete principios, desde el análisis de peligros hasta la documentación.<br>2. Un PCC exige límites críticos medibles, monitoreo y acciones correctivas predefinidas.<br>3. Es especialmente valioso para controlar peligros microbiológicos y de contaminación.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Cómo seleccionar y combinar herramientas de riesgo', 'Clase 4 · Selección de la herramienta adecuada', 7, 'manual')
