  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>El estudiante compara las herramientas de QRM según su propósito, sus requisitos de información y su formalidad, y justifica la elección para distintos escenarios.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 1, '{"url":"https://www.farmaceuticos.com/wp-content/uploads/2021/05/2018-Gestion-riegos-calidad-industria-farmaceutica.pdf","title":"ICH Q9 Gestión de Riesgos de Calidad (QRM): definiciones, proceso y herramientas (AMFE, FTA, APPCC, HAZOP, PHA)","description":"AEFI Sección Catalana (alojado en farmaceuticos.com) (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.who.int/publications/m/item/trs981-annex2","title":"[Página web] TRS 981 – Annex 2: WHO guidelines on quality risk management (2013)","description":"OMS / WHO (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: analizar comparativamente las herramientas de QRM para seleccionar y combinar la más adecuada para cada pregunta de riesgo.</p><p>Desarrollo: no existe una \"mejor herramienta\". La elección depende de cinco preguntas:<br>1. ¿Cuál es el objetivo? Identificar peligros, priorizar, analizar causas o controlar.<br>2. ¿En qué fase del ciclo de vida estamos? Concepto, diseño, operación o investigación.<br>3. ¿Cuánta información hay disponible? Poca información orienta a PHA o a matrices; mucha información permite AMEF, FMECA o FTA cuantitativo.<br>4. ¿Qué nivel de formalidad exige el riesgo?<br>5. ¿Qué capacidades tiene el equipo para aplicar la herramienta de forma correcta?</p><p>Comparación resumida:<br>- Ishikawa: identificación y organización de causas. Información requerida: baja. No cuantifica. Muy usado en investigaciones.<br>- PHA: identificación temprana de peligros. Información baja. Cualitativo con matriz. Proyectos nuevos.<br>- Ranking y filtrado: priorización de muchos elementos. Información media. Semicuantitativo. Proveedores, auditorías, recalificaciones.<br>- AMEF: evaluación detallada de modos de falla. Información media o alta. Semicuantitativo (NPR). Procesos y equipos existentes o diseños maduros.<br>- FMECA: AMEF con criticidad. Información alta, con datos de confiabilidad. Sistemas críticos.<br>- FTA: análisis deductivo de un evento. Información media o alta. Cualitativo o cuantitativo. Investigaciones y eventos graves con barreras múltiples.<br>- HACCP: control preventivo de peligros en puntos críticos. Información alta del proceso. Peligros microbiológicos, físicos y químicos.<br>- HAZOP: desviaciones del diseño con palabras guía. Información alta de diseño. Sistemas de servicios, procesos químicos de API.</p><p>Combinaciones frecuentes:<br>- Diagrama de flujo + Ishikawa para identificar, y luego AMEF para analizar y priorizar.<br>- PHA en la fase de concepto, AMEF en el diseño de detalle y HACCP en la operación.<br>- FTA para un evento grave, con AMEF para profundizar en cada rama.<br>- Ranking y filtrado para escoger qué procesos merecen un AMEF completo.</p><p>Errores frecuentes:<br>- Usar el AMEF para todo, incluso para riesgos triviales, lo que genera documentos extensos sin valor.<br>- Elegir la herramienta que \"pide el inspector\" en lugar de la que responde la pregunta.<br>- Aplicar herramientas cuantitativas sin datos, con lo que se obtienen números con falsa precisión.</p><p>Ejemplo aplicado:<br>Escenario 1: un laboratorio colombiano debe decidir cuáles de sus 120 equipos requieren recalificación este año. Herramienta: ranking y filtrado.<br>Escenario 2: la misma empresa recibe tres quejas por frascos de suspensión sin la cuchara dosificadora. Herramientas: diagrama de flujo + Ishikawa para la investigación y luego actualización del AMEF de empaque.<br>Escenario 3: diseño de un nuevo sistema de agua para inyectables. Herramientas: PHA en el concepto, AMEF o HAZOP en el diseño y HACCP para la operación rutinaria.</p><p>Puntos clave:<br>1. La elección de la herramienta se justifica por el objetivo, la fase, la información disponible y la formalidad.<br>2. Las herramientas se combinan: identificar, analizar y priorizar, y controlar.<br>3. La complejidad de la herramienta debe ser proporcional al riesgo.</p>"}'::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 4. Aplicaciones de la gestión de riesgos en el ciclo de vida del producto', 3)
