  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=kugFUE-Bz-M","provider":"youtube","videoId":"kugFUE-Bz-M","title":"Gestión de las BPM - Validación y Calificación - DQ, IQ, OQ, PQ","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=3PlNG6MSYJQ","provider":"youtube","videoId":"3PlNG6MSYJQ","title":"Webinar: Calificación de Equipos: Claves para Ejecutar con Éxito y Evitar Hallazgos","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.who.int/publications/m/item/trs981-annex2","title":"[Página web] TRS 981 – Annex 2: WHO guidelines on quality risk management (2013)","description":"OMS / WHO (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: aplicar la gestión de riesgos para decidir qué calificar o validar, con qué profundidad y con qué frecuencia de revisión.</p><p>Desarrollo: las BPM modernas, como el Anexo 15 de la UE y de PIC/S y las guías de la OMS sobre validación, establecen que la calificación y la validación deben basarse en la gestión de riesgos. Esto evita dos extremos: validar todo con la misma profundidad, con un desperdicio de recursos, o validar de menos en sistemas críticos.</p><p>Aplicaciones de la QRM:<br>1. Evaluación de impacto de sistemas: determinar si un sistema (HVAC, agua, aire comprimido, equipo de proceso) tiene impacto directo, indirecto o ningún impacto en la calidad del producto.<br>2. Evaluación de componentes críticos: dentro de un sistema de impacto directo, identificar los componentes y funciones críticas (por ejemplo, el sensor de temperatura de un autoclave frente a la pintura de la carcasa).<br>3. Definición del alcance de las pruebas: los requisitos de usuario (URS) de mayor riesgo requieren pruebas más exhaustivas en las calificaciones de instalación, operación y desempeño (IQ, OQ y PQ). El análisis de riesgos se vincula a una matriz de trazabilidad.<br>4. Validación de procesos: identificar los parámetros críticos de proceso (CPP) que deben controlarse y demostrarse, y decidir el número de lotes y el muestreo del enfoque de ciclo de vida (diseño, calificación y verificación continua).<br>5. Validación de limpieza: seleccionar el producto o \"peor caso\" (por toxicidad, solubilidad o dificultad de limpieza), los puntos de muestreo más difíciles de limpiar y los límites basados en salud.<br>6. Recalificación periódica: definir la frecuencia según la criticidad, el historial de fallas y los cambios.</p><p>Herramientas habituales: evaluación de impacto con árboles de decisión, AMEF de equipos o sistemas y ranking y filtrado para planificar recalificaciones.</p><p>Ejemplo aplicado: una empresa en Medellín adquiere una nueva tableteadora rotativa. Evaluación de riesgos:<br>- Impacto directo en el producto: sí, porque afecta el peso, la dureza y la uniformidad de contenido.<br>- Funciones críticas: control de fuerza de compresión, rechazo automático de tabletas fuera de peso, registro electrónico de datos y superficies en contacto con el producto.<br>- Funciones no críticas: la iluminación interna o el color del panel.<br>El AMEF de equipo identifica que una falla del sistema de rechazo tiene severidad 8. Por eso la OQ incluye pruebas de desafío del rechazo con tabletas fuera de peso. Las funciones de bajo riesgo se verifican de forma documental. La recalificación se fija cada dos años, salvo cambios o desviaciones. El sistema electrónico de registro se evalúa también desde la integridad de datos.</p><p>Puntos clave:<br>1. La QRM define el alcance y la profundidad de la calificación y la validación, empezando por la evaluación de impacto.<br>2. Las funciones críticas reciben pruebas exhaustivas; las no críticas, verificaciones proporcionales.<br>3. En limpieza, el riesgo orienta la selección del peor caso, los puntos de muestreo y los límites.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Control de cambios basado en riesgo', 'Clase 3 · QRM dentro del sistema de calidad', 3, 'video')
