  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>El estudiante interpreta la dimensión de disponibilidad de ICH Q9(R1) y la aplica a la identificación de vulnerabilidades de suministro en el contexto colombiano.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=EGhivyXMa5w","provider":"youtube","videoId":"EGhivyXMa5w","title":"Listado de medicamentos que, según el Invima, están escaseando en Colombia","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/VS/MET/2024-06-06-mesa-abastecimiento-todos-los-actores.pdf","title":"Mesa de trabajo abastecimiento de medicamentos – todos los actores de la cadena de suministro (6 jun. 2024)","description":"Ministerio de Salud y Protección Social (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/decreto_0334_2022.htm","title":"[Página web] Decreto 334 de 2022 – Renovación, modificación y suspensión de registros sanitarios de medicamentos; información, publicidad y desabastecimiento","description":"INVIMA – Normograma / MinSalud (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: interpretar el concepto de riesgo para la disponibilidad del producto e identificar medidas preventivas en una empresa colombiana.</p><p>Desarrollo: ICH Q9(R1) incorporó una sección sobre los riesgos para la disponibilidad del producto relacionados con la calidad y la fabricación. La razón es que los desabastecimientos de medicamentos, muchas veces causados por problemas de calidad o de capacidad de fabricación, dañan al paciente: interrumpen tratamientos y obligan a usar alternativas menos adecuadas. La guía señala que una QRM eficaz ayuda a prevenir estos problemas, y menciona factores como:<br>- Variabilidad del proceso y estado de control: los procesos poco robustos generan lotes rechazados y faltantes.<br>- Estado de las instalaciones y equipos: equipos antiguos sin mantenimiento preventivo, o un único equipo crítico sin respaldo.<br>- Supervisión de terceros: proveedores y fabricantes por contrato con problemas de cumplimiento.<br>- Gestión de cambios y mejora: la falta de inversión y de mejora continua aumenta el riesgo.</p><p>En Colombia, el desabastecimiento es un problema de salud pública recurrente. El INVIMA publica listados de medicamentos en seguimiento por riesgo de desabastecimiento y gestiona la figura de medicamentos vitales no disponibles. El Decreto 334 de 2022 incluye además medidas para prevenir el desabastecimiento. La figura de vitales no disponibles permite importar medicamentos indispensables que no se fabrican o no se comercializan en el país en cantidad suficiente. Para el QF de la industria, esto implica integrar la disponibilidad en la QRM.</p><p>¿Cómo integrar la disponibilidad en la evaluación de riesgos?<br>1. Identificar los productos críticos para la salud pública del portafolio: medicamentos esenciales, sin alternativas terapéuticas o con alta participación de mercado.<br>2. Mapear las vulnerabilidades de su cadena: proveedor único del API, un solo equipo, una sola línea, sitio de fabricación por contrato con hallazgos.<br>3. Analizar la probabilidad y el impacto de una interrupción, incluido el tiempo de recuperación.<br>4. Definir controles: proveedores alternos calificados, inventarios de seguridad, mantenimiento predictivo, mejora de la robustez del proceso y planes de continuidad.<br>5. Al tomar decisiones de calidad (por ejemplo, ante una desviación), considerar el impacto en la disponibilidad junto con el riesgo para el paciente. Nunca se compromete la seguridad, pero sí se buscan alternativas que eviten el desabastecimiento cuando la evidencia lo permite, en comunicación con la autoridad.</p><p>Ejemplo aplicado: un laboratorio colombiano es uno de los pocos fabricantes nacionales de una solución inyectable esencial para hospitales. Su evaluación de disponibilidad identifica que el principio activo proviene de un único fabricante en Asia y que la línea de llenado no tiene respaldo. Medidas: calificar un segundo proveedor del API, mantener un inventario de seguridad de seis meses de API, programar el mantenimiento mayor de la línea en temporadas de baja demanda y establecer un protocolo de comunicación temprana con el INVIMA si se prevé una interrupción. Cuando una desviación compromete parte de un lote, la decisión considera tanto la seguridad del paciente como el impacto de un rechazo total en el abastecimiento nacional, con soporte analítico.</p><p>Puntos clave:<br>1. Para ICH Q9(R1), la falta de disponibilidad del producto también es un daño para el paciente.<br>2. La robustez del proceso, el estado de los equipos y la supervisión de terceros son factores de riesgo de disponibilidad.<br>3. En Colombia, la QRM debe considerar los listados de seguimiento de desabastecimiento y la figura de vitales no disponibles.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Caso integrador: introducción de un nuevo producto en una planta multiproducto', 'Clase 3 · Caso integrador y programa de QRM', 3, 'manual')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>El estudiante ejecuta el proceso completo de QRM (inicio, evaluación, control, comunicación y revisión) sobre un caso realista que combina varias herramientas y aplicaciones.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 1, '{"url":"https://database.ich.org/sites/default/files/ICH%20Q9R1_Step_4_Presentation_2023_0314.pdf","title":"ICH Q9(R1): Quality Risk Management – Step 4 presentation (14 marzo 2023)","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.farmaceuticos.com/wp-content/uploads/2021/05/2018-Gestion-riegos-calidad-industria-farmaceutica.pdf","title":"ICH Q9 Gestión de Riesgos de Calidad (QRM): definiciones, proceso y herramientas (AMFE, FTA, APPCC, HAZOP, PHA)","description":"AEFI Sección Catalana (alojado en farmaceuticos.com) (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: integrar todo lo aprendido ejecutando el proceso de QRM completo sobre un caso realista.</p><p>Escenario: Laboratorios Andinos S.A.S. (empresa ficticia) tiene una planta de sólidos orales certificada en BPM por el INVIMA en el área metropolitana de Bogotá. Fabrica antihipertensivos, analgésicos y antiácidos. La gerencia decide introducir un nuevo producto: tabletas de un inmunosupresor de alta potencia, con estrecho margen terapéutico. Se fabricarían en el mismo tren de granulación y compresión, y el principio activo se compraría a un proveedor nuevo en India.</p><p>Paso 1. Inicio. Pregunta de riesgo: \"¿Puede fabricarse el nuevo inmunosupresor en el tren de sólidos existente protegiendo a los pacientes de los demás productos, a los pacientes del producto nuevo y a los operarios, y asegurando el suministro?\". Equipo: Dirección Técnica, aseguramiento de calidad, producción, control de calidad, ingeniería, salud ocupacional, compras y un toxicólogo externo. Formalidad: alta, por la incertidumbre, la importancia y la complejidad.</p><p>Paso 2. Evaluación.<br>- Identificación de peligros con diagrama de flujo e Ishikawa: contaminación cruzada por residuos del inmunosupresor, exposición de operarios al polvo, variabilidad del API del nuevo proveedor, falta de uniformidad de contenido (dosis bajas), riesgos de integridad de datos en el nuevo método analítico y dependencia de un único proveedor.<br>- Análisis: PDE del inmunosupresor calculada por el toxicólogo (muy baja). El MACO resultante exige límites de limpieza muy estrictos. AMEF del proceso: la uniformidad de contenido en el mezclado obtiene severidad 9. Ranking del proveedor: riesgo alto, por ser nuevo, ubicado en otro continente y crítico.<br>- Valoración: varios riesgos superan los criterios de aceptación; se requiere control.</p><p>Paso 3. Control.<br>- Contaminación cruzada: fabricación por campañas, limpieza validada con método analítico de alta sensibilidad, verificación analítica después de cada campaña, equipos de transferencia cerrados y diferenciales de presión reforzados. Se evalúa la alternativa de un área dedicada si la limpieza no alcanza los límites.<br>- Operarios: contención y protección respiratoria según la evaluación de salud ocupacional.<br>- Uniformidad: validación del mezclado con muestreo estratificado y un control en proceso reforzado.<br>- Proveedor: auditoría presencial antes de la aprobación, análisis completo de los primeros lotes y búsqueda de un segundo proveedor.<br>- Integridad de datos: validación del sistema cromatográfico y revisión de la pista de auditoría.<br>- Riesgo residual: aceptado formalmente por la Dirección Técnica con un plan de monitoreo.</p><p>Paso 4. Comunicación. Informe a la gerencia con los riesgos residuales y los costos de los controles. Trámites y comunicaciones ante el INVIMA según aplique (registro sanitario, ampliación de la certificación o notificación de nuevas líneas, según la normativa vigente). Capacitación del personal.</p><p>Paso 5. Revisión. Disparadores: cualquier resultado de limpieza fuera de límite, desviaciones del producto, cambios del proveedor y revisión anual de producto. Revisión formal programada a los 12 meses.</p><p>Actividad para el estudiante: elabore el registro de riesgos del caso con al menos 8 peligros, puntúelos con las escalas del curso, proponga controles y calcule el riesgo residual.</p><p>Puntos clave:<br>1. Un caso real combina varias herramientas: flujo, Ishikawa, PDE/MACO, AMEF y ranking.<br>2. Varias dimensiones de riesgo coexisten: pacientes, operarios, datos y disponibilidad.<br>3. La decisión final y la aceptación del riesgo residual deben ser explícitas, documentadas y revisables.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Diseño del programa de QRM de la empresa e informe de evaluación de riesgos', 'Clase 3 · Caso integrador y programa de QRM', 4, 'manual')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>El estudiante ejecuta la estructuración de un procedimiento maestro de QRM y de un informe de evaluación de riesgos que cumpla las expectativas de ICH Q9(R1) y del INVIMA.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 1, '{"url":"https://www.who.int/publications/m/item/trs981-annex2","title":"[Página web] TRS 981 – Annex 2: WHO guidelines on quality risk management (2013)","description":"OMS / WHO (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://health.ec.europa.eu/system/files/2023-10/mp_ich_q9guideline-ra_en.pdf","title":"ICH guideline Q9 (R1) on quality risk management (EMA/CHMP/ICH/24235/2006, 2023)","description":"ICH / EMA – Comisión Europea (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://database.ich.org/sites/default/files/ICH%20Q9R1_Step_4_Presentation_2023_0314.pdf","title":"ICH Q9(R1): Quality Risk Management – Step 4 presentation (14 marzo 2023)","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: ejecutar el diseño de los documentos que sostienen un programa de QRM: el procedimiento maestro y el formato de informe de evaluación de riesgos.</p><p>Desarrollo: un programa de QRM maduro no depende de personas aisladas que \"saben hacer AMEF\". Se apoya en documentos, roles y una cultura que integran el riesgo en las decisiones cotidianas. La documentación del sistema documental general se aborda en el curso de Documentación; aquí se definen los contenidos específicos de la QRM.</p><p>1. Procedimiento maestro de QRM (SOP). Contenido recomendado:<br>- Objeto y alcance: a qué procesos aplica (cambios, desviaciones, proveedores, validación, contaminación cruzada, distribución, integridad de datos, disponibilidad).<br>- Referencias: ICH Q9(R1), OMS TRS 981 Anexo 2, Resolución 1160 de 2016 y las normas colombianas vigentes aplicables.<br>- Definiciones alineadas con ICH Q9(R1).<br>- Roles y responsabilidades: patrocinador o tomador de decisión, líder o facilitador, miembros del equipo y quien acepta el riesgo residual (normalmente la Dirección Técnica o Aseguramiento de Calidad, según el nivel).<br>- Criterios para determinar el nivel de formalidad (incertidumbre, importancia y complejidad).<br>- Herramientas aprobadas y cuándo usar cada una.<br>- Escalas estandarizadas de severidad, probabilidad y detección, con descriptores concretos, y los criterios de aceptación.<br>- Gestión de la subjetividad: facilitación, puntuación individual, uso de datos.<br>- Comunicación y escalamiento: a la alta dirección y a la autoridad cuando aplique.<br>- Revisión: disparadores, frecuencia y mantenimiento del registro maestro de riesgos.<br>- Capacitación y calificación de facilitadores.</p><p>2. Formato de informe de evaluación de riesgos. Secciones mínimas:<br>- Identificación (código, título, fecha, versión) y pregunta de riesgo.<br>- Alcance, supuestos y exclusiones.<br>- Equipo y nivel de formalidad elegido, con su justificación.<br>- Información de base usada (datos, referencias).<br>- Herramienta utilizada y resultados (tabla AMEF, matriz, árbol, etc.).<br>- Valoración frente a los criterios.<br>- Acciones de control con responsables y fechas.<br>- Riesgo residual y declaración de aceptación con firma.<br>- Plan de comunicación y de revisión.<br>- Anexos y control de versiones.</p><p>3. Indicadores del programa: porcentaje de evaluaciones revisadas a tiempo, acciones de control cerradas en plazo, eficacia (reducción de desviaciones recurrentes en los procesos evaluados) y hallazgos de inspección relacionados con la QRM.</p><p>Ejemplo aplicado: Laboratorios Andinos S.A.S. (caso integrador) redacta su SOP maestro de QRM con tres niveles de formalidad. Nivel 1: evaluación integrada en el formato del proceso origen. Nivel 2: matriz de riesgo con justificación escrita. Nivel 3: herramienta formal (AMEF, HACCP o FTA) con informe independiente. Crea un registro maestro con 35 evaluaciones vigentes y capacita a seis facilitadores. A los seis meses, la autoinspección verifica una muestra de evaluaciones y encuentra escalas aplicadas de forma inconsistente. Se refuerza la capacitación y se ajustan los descriptores.</p><p>Puntos clave:<br>1. El procedimiento maestro de QRM define roles, formalidad, herramientas, escalas, criterios, comunicación y revisión.<br>2. El informe de evaluación de riesgos debe ser trazable, justificar la formalidad y documentar la aceptación del riesgo residual.<br>3. Los indicadores permiten demostrar que el programa de QRM funciona y mejora.</p>"}'::jsonb);

END
$curso$;

-- ─── 9. Curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA (35 clases) ───
DO $curso$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  -- Si ya está, no se duplica.
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, level,
     objective, audience, duration_minutes, author_name, status, modality)
  VALUES ('edvanta', 'Curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA', 'Curso práctico para gestionar desviaciones, investigar su causa raíz y diseñar acciones correctivas y preventivas efectivas en la industria farmacéutica colombiana. Integra la Resolución 1160 de 2016, ICH Q10, la guía FDA de OOS 2022 y las lecciones de inspecciones INVIMA y FDA.', '<p>Curso práctico para gestionar desviaciones, investigar su causa raíz y diseñar acciones correctivas y preventivas efectivas en la industria farmacéutica colombiana. Integra la Resolución 1160 de 2016, ICH Q10, la guía FDA de OOS 2022 y las lecciones de inspecciones INVIMA y FDA.</p><h3>Objetivo general</h3><p>Que el Químico Farmacéutico sea capaz de detectar, clasificar, contener e investigar desviaciones, resultados OOS y quejas, y de diseñar, implementar y verificar la efectividad de acciones CAPA conforme a la normativa colombiana y los referentes internacionales.</p><h3>A quién va dirigido</h3><p>Químicos Farmacéuticos, directores técnicos y profesionales de aseguramiento de calidad, control de calidad y producción en laboratorios farmacéuticos, cosméticos y establecimientos regulados por el INVIMA en Colombia.</p><h3>Contexto normativo</h3><p>Colombia — normativa INVIMA / MinSalud</p>',
          'Calidad farmacéutica', 'intermedio', 'Que el Químico Farmacéutico sea capaz de detectar, clasificar, contener e investigar desviaciones, resultados OOS y quejas, y de diseñar, implementar y verificar la efectividad de acciones CAPA conforme a la normativa colombiana y los referentes internacionales.', 'Químicos Farmacéuticos, directores técnicos y profesionales de aseguramiento de calidad, control de calidad y producción en laboratorios farmacéuticos, cosméticos y establecimientos regulados por el INVIMA en Colombia.',
          1200, 'Edvanta', 'borrador', 'asincronica')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos de las desviaciones y marco regulatorio', 0)
  RETURNING id INTO v_unidad;
