  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Desviación, no conformidad, OOS y queja: definiciones y diferencias', 'Clase 2 · ¿Qué es una desviación?', 1, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Describe qué es una desviación y cómo se diferencia de una no conformidad, un resultado OOS, una queja y un defecto de calidad.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=UMXpQKJ5YY0","provider":"youtube","videoId":"UMXpQKJ5YY0","title":"Desviaciones","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://health.ec.europa.eu/system/files/2016-11/vol4-chap1_2013-01_en_0.pdf","title":"EudraLex Vol. 4 – Capítulo 1: Pharmaceutical Quality System (desviaciones y CAPA, 1.4 xiv)","description":"Comisión Europea (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf","title":"Resolución 1160 de 2016 – Manuales de Buenas Prácticas de Manufactura y guías de inspección","description":"Ministerio de Salud y Protección Social de Colombia (ES)"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Desviaciones planeadas y no planeadas', 'Clase 2 · ¿Qué es una desviación?', 2, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Diferencia las desviaciones planeadas de las no planeadas, sus requisitos de aprobación y su relación con el control de cambios.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=ssFIvywjmZs","provider":"youtube","videoId":"ssFIvywjmZs","title":"Manejo de Desviaciones","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 2, '{"html":"<p>Objetivo: diferenciar una desviación planeada de una no planeada y saber cuándo cada una es aceptable dentro de un sistema de calidad conforme a la Resolución 1160 de 2016.</p><p>Desarrollo: una desviación es cualquier apartamiento de una instrucción aprobada (procedimiento, orden de producción, especificación, método analítico, condición ambiental o de equipo). La desviación NO PLANEADA ocurre de forma inesperada y se detecta después de que sucede: un tiempo de mezcla que excede lo establecido, una excursión de temperatura en bodega, una etiqueta errada en línea. Exige registro inmediato, contención, evaluación de impacto e investigación proporcional al riesgo.</p><p>La desviación PLANEADA (también llamada temporal o autorizada) es un apartamiento intencional, previamente evaluado y aprobado por Aseguramiento de la Calidad antes de ejecutarse, con alcance limitado en tiempo o número de lotes. Ejemplos: usar por una sola vez un equipo equivalente porque el habitual está en mantenimiento correctivo, o aceptar un proveedor alterno ya calificado mientras se completa el cambio documental. Requisitos mínimos: justificación técnica, evaluación de riesgo (ICH Q9), definición de lotes afectados, controles adicionales y aprobación previa de la Dirección Técnica y de Calidad.</p><p>Error frecuente: usar la desviación planeada para evitar el control de cambios. Si la condición se va a volver permanente o se repite, el camino correcto es un control de cambios; las desviaciones planeadas repetidas sobre lo mismo son un hallazgo típico de inspección, porque revelan un procedimiento que no refleja la realidad de la planta.</p><p>Ejemplo aplicado: un laboratorio en Bogotá fabrica tabletas y su tableteadora principal falla. Producción propone usar la tableteadora B, que tiene IQ/OQ vigentes pero no tiene PQ para ese producto. Calidad abre una desviación planeada para un lote, define muestreo reforzado de dureza, friabilidad y uniformidad de contenido, y la aprueba antes de iniciar. Si durante la fabricación se detecta que la tableteadora B trabajó a una velocidad no evaluada, eso ya es una desviación NO planeada dentro de la planeada y debe registrarse e investigarse por separado. Ante un inspector del INVIMA, la planta debe poder demostrar la aprobación previa, los resultados de los controles y la decisión final sobre el lote.</p><p>Puntos clave:<br>1. La desviación planeada se aprueba ANTES de ejecutarse; la no planeada se registra DESPUÉS de detectarse.<br>2. Ambas requieren evaluación de riesgo e impacto documentada y decisión de Calidad sobre el lote.<br>3. Una desviación planeada que se repite es una señal de que se necesita un control de cambios, no otra desviación.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Clasificación por criticidad: crítica, mayor y menor', 'Clase 2 · ¿Qué es una desviación?', 3, 'video')
