  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Flujo del reporte: formato, roles y plazos', 'Clase 2 · Detección y registro', 2, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica el flujo de reporte de una desviación con contenido mínimo del formato, roles, plazos y vinculación con el registro de lote.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=DMK9fzutzlg","provider":"youtube","videoId":"DMK9fzutzlg","title":"Mastering Deviation Management in the Life Science Industry","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 2, '{"html":"<p>Objetivo: describir el flujo del reporte de una desviación, desde su detección hasta su clasificación inicial, con roles, plazos y contenido mínimo del formato.</p><p>Desarrollo: un buen sistema de desviaciones depende de que el reporte sea rápido, completo y sin culpas. El flujo típico tiene cinco pasos:<br>1) Detección y notificación inmediata: quien detecta (operario, analista, auxiliar de bodega) detiene la actividad si hay riesgo y avisa a su jefe inmediato y a Aseguramiento de la Calidad el mismo turno.<br>2) Registro: se abre el formato de desviación (físico o electrónico) con número consecutivo único. Contenido mínimo: qué ocurrió, dónde, cuándo, quién lo detectó, producto/lote/equipo/material implicado, instrucción incumplida (código y versión del POE o de la orden), evidencia (fotos, impresiones, registros) y acciones inmediatas tomadas.<br>3) Clasificación inicial: Calidad, junto con el área, asigna una clasificación preliminar (crítica, mayor o menor) basada en riesgo para el paciente, calidad del producto y cumplimiento regulatorio. Esta clasificación puede ajustarse cuando avance la investigación.<br>4) Asignación de responsables y plazos: se nombra un líder de investigación. Una práctica común en la industria es cerrar la investigación en 30 días calendario, con extensiones justificadas y aprobadas; las desviaciones críticas se escalan de inmediato a la Dirección Técnica.<br>5) Vinculación: el número de desviación se cita en el registro del lote, en el expediente de liberación y, si aplica, en el CAPA y en el control de cambios.</p><p>Cultura de reporte: si el personal teme ser sancionado, oculta o demora el reporte. El POE debe declarar explícitamente que reportar es una obligación y que la investigación busca causas del sistema, no culpables.</p><p>Ejemplo aplicado: en una planta de líquidos orales en Medellín, una auxiliar de dispensación nota que la balanza de 30 kg tiene la etiqueta de calibración vencida desde hace dos días. Suspende la dispensación, avisa a su coordinadora y a Calidad, y diligencia el formato DV-2026-087 indicando los lotes pesados en esos dos días. Calidad clasifica preliminarmente como mayor, retiene los lotes y asigna a Metrología para verificar la balanza con pesas patrón. El inspector del INVIMA, al revisar el registro de lote, encontrará la referencia cruzada a la desviación y la trazabilidad de la decisión.</p><p>Puntos clave:<br>1. Notificar el mismo turno y registrar con número único y evidencia objetiva.<br>2. Clasificación preliminar por riesgo, con responsable y plazo definidos; escalar las críticas.<br>3. El reporte debe estar vinculado al registro de lote y nunca debe castigarse a quien reporta.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Acciones inmediatas de contención', 'Clase 3 · Contención y evaluación de impacto', 3, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Ejecuta acciones de contención (retención, cuarentena, suspensión de equipos, bloqueo de despachos) y las distingue de las acciones correctivas.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=A-ecFdOvyzk","provider":"youtube","videoId":"A-ecFdOvyzk","title":"Correcciones, acciones correctivas y preventivas","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 2, '{"html":"<p>Objetivo: aplicar acciones inmediatas de contención que protejan al paciente y al producto mientras se investiga la causa raíz.</p><p>Desarrollo: la contención (también llamada corrección o acción inmediata) no elimina la causa; limita el daño. Debe ejecutarse en horas, no en días, y quedar documentada en el formato de la desviación. Preguntas guía:<br>- ¿Qué está afectado ahora? Producto en proceso, lotes terminados, materias primas, equipos, áreas.<br>- ¿Qué podría estar afectado? Otros lotes fabricados con el mismo equipo, material, analista o método durante el mismo periodo.<br>- ¿Qué debo detener? Fabricación, análisis, despacho, uso de un lote de materia prima.</p><p>Acciones típicas de contención:<br>1) Poner en cuarentena o retener lotes (estado \"retenido\" en el sistema y rotulación física).<br>2) Suspender el uso de un equipo o instrumento e identificarlo \"fuera de servicio\".<br>3) Segregar material sospechoso (por ejemplo, rollos de etiquetas con impresión defectuosa).<br>4) Bloquear despachos en el sistema de inventario y, si el producto ya salió, evaluar con la Dirección Técnica la necesidad de detener distribución o iniciar un retiro.<br>5) Verificaciones al 100 % o muestreo reforzado para delimitar el alcance.</p><p>Diferencia clave: corrección = arreglar el efecto (reetiquetar, recalibrar); acción correctiva = eliminar la causa para que no se repita; acción preventiva = eliminar la causa de un problema potencial. Confundirlas es un error frecuente en los formatos.</p><p>Ejemplo aplicado: durante el acondicionamiento de un antihipertensivo en una planta de Cali, una operaria encuentra un blíster con tabletas de otro color. Contención inmediata: se detiene la línea, se segregan todas las cajas acondicionadas del turno, se hace despeje de línea completo, se retienen el lote actual y el lote previo que corrió en la misma blistera, y se revisa al 100 % el producto del turno. Calidad documenta todo en la desviación y notifica a la Dirección Técnica. Solo después se inicia la investigación de causa raíz (despeje de línea, diseño del área, controles de visión artificial). Si existiera riesgo de producto ya distribuido, se evaluaría el reporte al INVIMA y un posible retiro de mercado.</p><p>Puntos clave:<br>1. Contener primero, investigar después: la contención se ejecuta en horas y se documenta.<br>2. Delimitar el alcance: incluir lotes y materiales potencialmente afectados, no solo el evidente.<br>3. La contención es una corrección; no reemplaza la acción correctiva sobre la causa raíz.</p>"}'::jsonb);
