  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=3JIan8ANoCc","provider":"youtube","videoId":"3JIan8ANoCc","title":"Herramientas de Calidad: Diagrama Pareto","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 2, '{"html":"<p>Objetivo: interpretar tendencias e indicadores del sistema de desviaciones y CAPA para detectar problemas recurrentes y evaluar la salud del sistema de calidad.</p><p>Desarrollo: ICH Q10 pide que el sistema CAPA y la revisión por la dirección usen datos de desviaciones, quejas, auditorías y monitoreo para identificar tendencias. Un caso aislado se investiga; un patrón exige una acción sistémica. Para detectar patrones se categoriza cada desviación con campos estandarizados: área, producto, equipo, tipo de evento (documental, de proceso, de equipo, de laboratorio, de material) y categoría de causa raíz (método, máquina, material, mano de obra, medición, medio ambiente; o error humano tipo deslizamiento, lapsus, equivocación o violación).</p><p>Indicadores (KPI) frecuentes:<br>1) Número de desviaciones por mes y por área, normalizado por lotes fabricados.<br>2) Porcentaje de desviaciones cerradas a tiempo (meta típica ≥ 90 % en 30 días).<br>3) Edad promedio de desviaciones y CAPA abiertas, y número de extensiones.<br>4) Tasa de recurrencia: desviaciones con la misma causa raíz en 12 meses.<br>5) Porcentaje de investigaciones con causa raíz \"error humano\" (un valor alto suele indicar investigaciones superficiales).<br>6) Porcentaje de CAPA efectivas en la verificación de efectividad.<br>7) Desviaciones por criticidad (críticas, mayores, menores).</p><p>Herramientas: gráficos de Pareto por causa y por área, gráficos de control o de corrida por mes, y matrices producto vs. tipo de evento. Las tendencias se presentan en el comité de calidad mensual y alimentan la Revisión Anual de Producto exigida en las BPM de la Resolución 1160 de 2016.</p><p>Ejemplo aplicado: una planta de sólidos en Itagüí revisa su Pareto trimestral y encuentra que el 40 % de las desviaciones son \"errores de documentación\" en registros de lote, concentradas en el turno de la noche. Individualmente todas eran menores y se cerraron con \"reentrenamiento\". La tendencia muestra que el problema es sistémico: el formato del registro de lote tiene 60 páginas, campos ambiguos y se diligencia al final del turno. Se abre una CAPA sistémica para rediseñar el registro y evaluar la carga de trabajo nocturna. A los seis meses el indicador baja a 12 %. Un inspector del INVIMA valorará más esta gestión de tendencias que el cierre puntual de cada evento.</p><p>Puntos clave:<br>1. Categorice cada desviación con campos estandarizados para poder hacer tendencias.<br>2. Combine indicadores de volumen, oportunidad, recurrencia y efectividad.<br>3. Varias desviaciones menores con la misma causa son un problema mayor que exige CAPA sistémica.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Relación con control de cambios, cierre y documentación', 'Clase 3 · Efectividad, tendencias, control de cambios y cierre', 6, 'video')
  RETURNING id INTO v_clase;
