-- ─── 10. Curso de Validación de Métodos Analíticos (33 clases) ───
DO $curso$
DECLARE
  v_curso  BIGINT;
  v_unidad BIGINT;
  v_clase  BIGINT;
BEGIN
  -- Si ya está, no se duplica.
  IF EXISTS (SELECT 1 FROM aula_courses WHERE title = 'Curso de Validación de Métodos Analíticos' AND deleted_at IS NULL) THEN
    RETURN;
  END IF;

  INSERT INTO aula_courses
    (kind, title, short_description, description_html, category, level,
     objective, audience, duration_minutes, author_name, status, modality)
  VALUES ('edvanta', 'Curso de Validación de Métodos Analíticos', 'Curso práctico para demostrar que los métodos analíticos farmacéuticos son aptos para su uso previsto, conforme a ICH Q2(R2), ICH Q14, USP y la normativa colombiana del INVIMA. Integra parámetros de desempeño, estadística aplicada en Excel, métodos indicadores de estabilidad y microbiológicos, documentación y ciclo de vida, con casos de HPLC y UV-Vis.', '<p>Curso práctico para demostrar que los métodos analíticos farmacéuticos son aptos para su uso previsto, conforme a ICH Q2(R2), ICH Q14, USP y la normativa colombiana del INVIMA. Integra parámetros de desempeño, estadística aplicada en Excel, métodos indicadores de estabilidad y microbiológicos, documentación y ciclo de vida, con casos de HPLC y UV-Vis.</p><h3>Objetivo general</h3><p>Que el Químico Farmacéutico diseñe, ejecute, evalúe estadísticamente y documente la validación, verificación y transferencia de métodos analíticos farmacéuticos según ICH Q2(R2)/Q14, USP y los requisitos INVIMA, gestionando su ciclo de vida.</p><h3>A quién va dirigido</h3><p>Químicos Farmacéuticos, analistas y jefes de control de calidad, profesionales de asuntos regulatorios y aseguramiento de calidad de la industria farmacéutica colombiana, y estudiantes de últimos semestres de Química Farmacéutica.</p><h3>Contexto normativo</h3><p>Colombia — normativa INVIMA / MinSalud</p>',
          'Calidad farmacéutica', 'intermedio', 'Que el Químico Farmacéutico diseñe, ejecute, evalúe estadísticamente y documente la validación, verificación y transferencia de métodos analíticos farmacéuticos según ICH Q2(R2)/Q14, USP y los requisitos INVIMA, gestionando su ciclo de vida.', 'Químicos Farmacéuticos, analistas y jefes de control de calidad, profesionales de asuntos regulatorios y aseguramiento de calidad de la industria farmacéutica colombiana, y estudiantes de últimos semestres de Química Farmacéutica.',
          1200, 'Edvanta', 'borrador', 'asincronica')
  RETURNING id INTO v_curso;

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 1. Fundamentos y marco regulatorio de la validación analítica', 0)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Introducción al curso', 'Clase 1 · Introducción al curso', 0, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Presenta el propósito del curso, por qué un método analítico debe demostrar su aptitud para el uso previsto y cómo se conecta con la calidad del medicamento y el registro sanitario en Colombia.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=6c1Ei3UIMVI","provider":"youtube","videoId":"6c1Ei3UIMVI","title":"VALIDACIÓN de Procesos y Métodos Analíticos","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://database.ich.org/sites/default/files/ICH_Q2%28R2%29_Guideline_2023_1130.pdf","title":"ICH Q2(R2) Validation of Analytical Procedures (Guideline final, 2023)","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://www.eurachem.org/images/stories/Guides/pdf/MV_guide_2nd_ed_ES.pdf","title":"La Adecuación al Uso de los Métodos Analíticos: Guía de Laboratorio para Validación de Métodos y Temas Relacionados (Eurachem, 1.ª ed. en español)","description":"Eurachem (ES)"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'ICH Q2(R2) e ICH Q14: el nuevo enfoque de ciclo de vida', 'Clase 2 · Marco normativo internacional y nacional', 1, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Comprende la estructura de ICH Q2(R2) (2023) y su complemento ICH Q14, incluido el perfil objetivo analítico (ATP) y el enfoque mínimo frente al mejorado.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=48KNrCNAOIg","provider":"youtube","videoId":"48KNrCNAOIg","title":"ICH Q2R2 & Q14 Guidelines for Analytical Method Validation and Development","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://database.ich.org/sites/default/files/ICH_Q2%28R2%29_Guideline_2023_1130.pdf","title":"ICH Q2(R2) Validation of Analytical Procedures (Guideline final, 2023)","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://database.ich.org/sites/default/files/ICH_Q14_Guideline_2023_1116.pdf","title":"ICH Q14 Analytical Procedure Development (Guideline final, 2023)","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'USP <1225>, <1226>, <1224>, <1220> y guías OMS', 'Clase 2 · Marco normativo internacional y nacional', 2, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Describe el alcance de los capítulos USP sobre validación, verificación, transferencia y ciclo de vida, y las guías OMS que sustentan la normativa colombiana.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=cnQHShnPQA8","provider":"youtube","videoId":"cnQHShnPQA8","title":"Validation, Verification, & Transfer of Analytical Methods","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://cdn.who.int/media/docs/default-source/medicines/norms-and-standards/guidelines/production/trs1019-annex3-gmp-validation.pdf?sfvrsn=9440a5c_0&download=true","title":"WHO TRS 1019 - Annex 3: Good manufacturing practices: guidelines on validation","description":"OMS (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://dcvmn.org/wp-content/uploads/2017/01/who_guideline_validation_analyticalmethodvalidationqas16-671.pdf","title":"Guidelines on Validation - Appendix 4: Analytical Method Validation (borrador QAS/16.671, base del apéndice de TRS 1019)","description":"OMS (alojado por DCVMN) (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: describir el alcance de los capítulos generales de la USP sobre el ciclo de vida de los procedimientos analíticos y de las guías de la OMS, y ubicarlos frente a ICH Q2(R2) y la normativa colombiana.</p><p>Desarrollo. La Farmacopea de los Estados Unidos (USP), referencia oficial en Colombia junto con otras farmacopeas reconocidas por el INVIMA, organiza el tema en cuatro capítulos informativos (numeración superior a 1000, es decir, guías y no requisitos obligatorios por sí mismos):<br>- &lt;1225&gt; Validación de procedimientos farmacopeicos: define las características de desempeño (exactitud, precisión, especificidad, límite de detección, límite de cuantificación, linealidad, rango y robustez) y clasifica los procedimientos en cuatro categorías: I (cuantificación de componentes principales o activos), II (impurezas o productos de degradación, cuantitativos o prueba límite), III (características de desempeño como disolución o liberación) y IV (pruebas de identificación). Para cada categoría indica qué parámetros se requieren.<br>- &lt;1226&gt; Verificación de procedimientos farmacopeicos: establece que un método oficial no necesita validarse de nuevo, pero el laboratorio debe demostrar que funciona en sus condiciones reales de uso (su muestra, sus equipos, su personal).<br>- &lt;1224&gt; Transferencia de procedimientos analíticos: describe cómo trasladar un método validado de un laboratorio emisor a uno receptor, mediante pruebas comparativas, covalidación, revalidación parcial o exención justificada.<br>- &lt;1220&gt; Ciclo de vida del procedimiento analítico: integra diseño (perfil objetivo analítico, ATP), calificación del desempeño y verificación continua, en línea con la filosofía de ICH Q14.</p><p>La OMS, en su Serie de Informes Técnicos (TRS), publica guías de buenas prácticas de fabricación y de laboratorio con un apéndice dedicado a la validación de procedimientos analíticos (TRS 1019, 2019). Estas guías son la base técnica de la Resolución 3619 de 2013 del Ministerio de Salud de Colombia, que adopta el Manual de Buenas Prácticas de Laboratorio de Control de Calidad.</p><p>Ejemplo aplicado. Un laboratorio farmacéutico en Bogotá recibe una auditoría del INVIMA para certificación BPL. Para la valoración de tabletas de losartán por HPLC (método de la USP vigente) el auditor no exige una validación completa, sino evidencia de verificación según &lt;1226&gt;: especificidad frente a los excipientes de la fórmula propia, precisión (repetibilidad) y, si la matriz lo amerita, exactitud. En cambio, para un método desarrollado internamente para cuantificar un conservante no farmacopeico, el auditor solicita el protocolo e informe de validación completa según &lt;1225&gt; e ICH Q2(R2).</p><p>Puntos clave:<br>1. &lt;1225&gt; valida, &lt;1226&gt; verifica, &lt;1224&gt; transfiere y &lt;1220&gt; integra todo en un ciclo de vida.<br>2. La categoría del método (I a IV) determina qué parámetros deben evaluarse.<br>3. En Colombia, la Res. 3619 de 2013 (basada en la OMS) convierte estas buenas prácticas en requisito verificable por el INVIMA.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Normativa colombiana: Res. 3619 de 2013 y requisitos INVIMA', 'Clase 2 · Marco normativo internacional y nacional', 3, 'manual')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Identifica las exigencias de validación y verificación de métodos en el Manual de BPL de control de calidad y su relación con la evaluación farmacéutica del registro sanitario INVIMA.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 1, '{"url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3619-de-2013.pdf","title":"Resolución 3619 de 2013 - Manual de Buenas Prácticas de Laboratorio de Control de Calidad de Productos Farmacéuticos","description":"MinSalud Colombia (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.invima.gov.co/biblioteca/download/122391","title":"Comparativo normativo entre estándares de calidad (RNL) y Buenas Prácticas de Laboratorio farmacéutico (2019)","description":"INVIMA - Oficina de Laboratorios y Control de Calidad (ES)"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Validación, verificación, transferencia y calificación', 'Clase 3 · Conceptos base', 4, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Diferencia cada actividad y aprende a decidir cuál aplica según el origen del método y los cambios realizados.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=RHj-beVXxZk","provider":"youtube","videoId":"RHj-beVXxZk","title":"¿Validación o verificación de métodos? Descubre la gran diferencia","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 2, '{"url":"https://www.invima.gov.co/biblioteca/preview/122380","title":"[Página web] Validación de métodos analíticos (presentación: cuándo validar, parámetros, ANOVA, robustez)","description":"INVIMA (ES)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: diferenciar con precisión validación, verificación, transferencia y calificación de equipos, para decidir qué actividad corresponde en cada situación del laboratorio.</p><p>Desarrollo. Los cuatro términos se confunden con frecuencia en auditorías y en los expedientes de registro sanitario:<br>- Validación: proceso documentado que demuestra, mediante estudios de laboratorio, que las características de desempeño de un procedimiento cumplen los requisitos de su uso previsto (ICH Q2(R2)). Aplica a métodos nuevos, no farmacopeicos o farmacopeicos modificados fuera de lo permitido.<br>- Verificación: demostración de que un método oficial (farmacopeico) o ya validado funciona adecuadamente en las condiciones reales del laboratorio usuario (USP &lt;1226&gt;). Es un subconjunto de parámetros, escogidos según el riesgo.<br>- Transferencia: proceso documentado que califica a un laboratorio receptor para usar un método que fue desarrollado y validado en otro laboratorio emisor (USP &lt;1224&gt;). Típico entre casa matriz y planta local, o entre fabricante y laboratorio tercero.<br>- Calificación de equipos (DQ, IQ, OQ, PQ): demuestra que el instrumento (HPLC, espectrofotómetro, balanza) es apto. Es un requisito previo: no se puede validar un método en un equipo no calificado.</p><p>Árbol de decisión práctico:<br>1. ¿El método está en una farmacopea oficial y se usa sin modificaciones? Entonces se verifica.<br>2. ¿Fue validado en otro laboratorio y se va a usar aquí? Entonces se transfiere.<br>3. ¿Es nuevo, propio, o se modificó por fuera de los ajustes permitidos (por ejemplo, USP &lt;621&gt; para cromatografía)? Entonces se valida.<br>4. En todos los casos, los equipos deben estar calificados y la idoneidad del sistema debe cumplirse en cada corrida.</p><p>Ejemplo aplicado. Un laboratorio de Medellín fabrica un jarabe de ibuprofeno para un titular extranjero. La casa matriz envía el método validado de valoración por HPLC. El laboratorio local no debe validar de cero: debe ejecutar un protocolo de transferencia con pruebas comparativas (ambos laboratorios analizan los mismos lotes y se comparan medias y precisiones con criterios previos). Si luego el laboratorio cambia la columna a otra de dimensiones distintas, por fuera de lo permitido en el procedimiento, debe evaluar una revalidación parcial y documentarla mediante control de cambios, lo cual será revisado por el INVIMA en la inspección BPL.</p><p>Puntos clave:<br>1. Validar demuestra aptitud; verificar confirma aptitud en las condiciones propias; transferir califica a un nuevo laboratorio.<br>2. La calificación de equipos es prerrequisito, no sustituto, de la validación.<br>3. Toda modificación de un método debe pasar por control de cambios y evaluación de impacto en su estado validado.</p>"}'::jsonb);
