  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Métodos microbiológicos alternativos (USP <1223>)', 'Clase 3 · Validación de métodos microbiológicos', 3, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Interpreta los parámetros y la demostración de equivalencia para validar métodos microbiológicos rápidos.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=BfB57dSZUt8","provider":"youtube","videoId":"BfB57dSZUt8","title":"Validación de Métodos Microbiológicos","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=3wx5wiOsg4U","provider":"youtube","videoId":"3wx5wiOsg4U","title":"Rapid Sterility Testing: An Alternative Microbiological Method","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: interpretar los principios de USP &lt;1223&gt; para validar métodos microbiológicos alternativos (rápidos) frente a los métodos compendiales.</p><p>Desarrollo. Los métodos microbiológicos difieren de los fisicoquímicos: trabajan con organismos vivos, con alta variabilidad intrínseca (distribución de Poisson a bajos recuentos) y con respuestas que dependen de la recuperación y crecimiento del microorganismo. USP &lt;1223&gt; \"Validación de métodos microbiológicos alternativos\" establece cómo demostrar que un método alternativo (por ejemplo, bioluminiscencia ATP, citometría de flujo, PCR, detección por CO2 en sistemas automatizados) es equivalente o no inferior al método farmacopeico (&lt;61&gt;, &lt;62&gt;, &lt;71&gt;).</p><p>Clasifica las pruebas en tres tipos:<br>- Cualitativas (presencia/ausencia, por ejemplo esterilidad o ausencia de E. coli): se evalúan especificidad, límite de detección, robustez y equivalencia/no inferioridad.<br>- Cuantitativas (recuento de microorganismos aerobios, hongos y levaduras): exactitud, precisión, especificidad, límite de cuantificación, linealidad, rango, robustez y equivalencia.<br>- Identificación: exactitud de identificación frente a cepas de referencia.</p><p>Elementos prácticos: uso de cepas de referencia (ATCC o equivalentes) y aislamientos ambientales propios; inóculos bajos (menos de 100 UFC) para retar la sensibilidad; réplicas suficientes para el análisis estadístico (frecuentemente con transformación logarítmica de recuentos); y calificación del equipo (IQ/OQ/PQ) antes de la validación del método. La demostración de equivalencia puede ser por resultado aceptable, por desempeño o por decisión (la misma decisión de aceptación/rechazo del lote).</p><p>Ejemplo aplicado. Una planta de soluciones parenterales en Cali quiere reemplazar la prueba de esterilidad de 14 días por un sistema rápido basado en detección de crecimiento. Según &lt;1223&gt;, diseña un protocolo con cepas del capítulo &lt;71&gt; y aislamientos de su monitoreo ambiental, inóculos bajos, comparación de tasas de detección con el método compendial y análisis de no inferioridad. Antes de implementarlo en liberación de lotes, presenta el cambio mediante control de cambios y lo notifica al INVIMA dentro del trámite de modificación del registro sanitario cuando aplique.</p><p>Puntos clave:<br>1. Los métodos microbiológicos alternativos se validan por equivalencia o no inferioridad frente al compendial.<br>2. Los parámetros dependen del tipo de prueba: cualitativa, cuantitativa o de identificación.<br>3. Use cepas de referencia y aislamientos propios, inóculos bajos y estadística adecuada para datos microbiológicos.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Aptitud de métodos microbiológicos farmacopeicos', 'Clase 3 · Validación de métodos microbiológicos', 4, 'video')
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica la prueba de aptitud y las estrategias de neutralización en recuento, microorganismos específicos y esterilidad.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=lQwLEbrhkmc","provider":"youtube","videoId":"lQwLEbrhkmc","title":"Introducción a la Validación de Métodos Microbiológicos","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=Ap-nvLesUtc","provider":"youtube","videoId":"Ap-nvLesUtc","title":"Microbial Limit test (MLT) Protocol, steps and procedure in Pharmaceuticals & cosmetics USP 61 & 62","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Objetivo: aplicar la verificación de aptitud (method suitability) de los métodos microbiológicos farmacopeicos a un producto específico.</p><p>Desarrollo. Un método microbiológico oficial no se valida, pero sí debe demostrarse que funciona con el producto, porque muchos medicamentos tienen actividad antimicrobiana propia (conservantes, antibióticos, pH extremo) que puede inhibir la recuperación de microorganismos y dar falsos negativos.<br>- Recuento microbiano (USP &lt;61&gt;): se inoculan no más de 100 UFC de cada cepa indicada (S. aureus, P. aeruginosa, B. subtilis, C. albicans, A. brasiliensis) en presencia del producto. La recuperación debe estar dentro de un factor de 2 respecto al control sin producto (50–200 %). Si no se cumple, se neutraliza la actividad: dilución, polisorbato 80 y lecitina, filtración por membrana con lavados, o neutralizantes específicos.<br>- Microorganismos específicos (USP &lt;62&gt;): se demuestra que el método detecta E. coli, Salmonella, P. aeruginosa, S. aureus, Candida albicans u otros indicados, en presencia del producto.<br>- Esterilidad (USP &lt;71&gt;): prueba de bacteriostasis/fungistasis con no más de 100 UFC; el crecimiento debe ser visualmente comparable al control.<br>Además, cada lote de medio de cultivo debe pasar promoción de crecimiento, y las cepas deben mantenerse con no más de cinco pases desde el cultivo de referencia.<br>La prueba de aptitud debe repetirse cuando cambia la formulación, el proveedor de una materia prima relevante o las condiciones del método (diluyente, volumen filtrado, número de lavados). También es buena práctica registrar el lote de cada medio, la cepa y su número de pase, el conteo real del inóculo y la identidad del analista, de modo que el resultado sea trazable y reproducible durante una auditoría.</p><p>Ejemplo aplicado. Un laboratorio de Barranquilla analiza una crema con parabenos. En la prueba de aptitud según &lt;61&gt;, P. aeruginosa recupera solo 30 % frente al control. El analista diluye 1:100 con caldo con polisorbato 80 y lecitina; la recuperación sube a 85 % y el método queda verificado. La dilución empleada se incorpora al procedimiento de análisis y el informe se archiva como evidencia para la inspección BPL del INVIMA bajo la Res. 3619 de 2013.</p><p>Puntos clave:<br>1. Los métodos microbiológicos farmacopeicos requieren prueba de aptitud con el producto.<br>2. Criterio clave en recuentos: recuperación entre 50 % y 200 % del control.<br>3. Documente la estrategia de neutralización e incorpórela al método rutinario.</p>"}'::jsonb);

