  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Verificación de métodos farmacopeicos (USP <1226>)', 'Clase 3 · Verificación, transferencia y ciclo de vida', 3, 'video')
