  VALUES (v_clase, 'texto', 0, '{"html":"<p>Interpreta las estrategias de transferencia y diseña criterios de aceptación entre laboratorio emisor y receptor.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=fAHjpbnpaDk","provider":"youtube","videoId":"fAHjpbnpaDk","title":"Transfer of Analytical Methods and Procedures according to USP 1224","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=cnQHShnPQA8","provider":"youtube","videoId":"cnQHShnPQA8","title":"Validation, Verification, & Transfer of Analytical Methods","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://cdn.who.int/media/docs/default-source/medicines/norms-and-standards/guidelines/production/trs1019-annex3-gmp-validation.pdf?sfvrsn=9440a5c_0&download=true","title":"WHO TRS 1019 - Annex 3: Good manufacturing practices: guidelines on validation","description":"OMS (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: interpretar las estrategias de transferencia de procedimientos analíticos de USP &lt;1224&gt; y diseñar un protocolo de transferencia con criterios de aceptación.</p><p>Desarrollo. La transferencia califica al laboratorio receptor para ejecutar un método validado en el laboratorio emisor. Es frecuente en Colombia cuando un titular contrata fabricación o análisis con terceros, cuando se traslada producción entre plantas o cuando una multinacional importa productos y realiza el control en un laboratorio local.</p><p>Estrategias (USP &lt;1224&gt;):<br>1. Pruebas comparativas: ambos laboratorios analizan muestras homogéneas del mismo lote (o lotes) y se comparan resultados con criterios predefinidos, por ejemplo diferencia de medias de valoración menor o igual a 2,0 % y CV dentro de lo establecido en la validación. Puede aplicarse una prueba de equivalencia (dos pruebas t unilaterales, TOST).<br>2. Covalidación: el laboratorio receptor participa en la validación original, normalmente aportando datos de precisión intermedia/reproducibilidad.<br>3. Revalidación o validación parcial: el receptor repite los parámetros que pueden verse afectados por el cambio de laboratorio.<br>4. Exención de transferencia: justificada cuando el método es farmacopeico (aplica verificación), cuando el receptor ya domina un método muy similar o cuando el personal responsable se traslada al receptor.</p><p>Contenido del protocolo: objetivo y alcance, responsabilidades de cada laboratorio, materiales (lotes, estándares, columnas), procedimiento analítico, diseño experimental (número de analistas, días y réplicas), criterios de aceptación y manejo de desviaciones. El informe concluye si el receptor queda calificado.</p><p>Ejemplo aplicado. Un laboratorio farmacéutico de Bogotá recibe de su casa matriz en México el método HPLC de disolución de un comprimido de liberación prolongada. Se acuerdan pruebas comparativas: dos analistas del receptor, en días diferentes, analizan tres lotes; criterio: diferencia en el porcentaje disuelto de 5 % o menos en cada punto, y factor de similitud f2 de 50 o más frente a los perfiles del emisor. Un resultado fuera de criterio se investiga como desviación antes de concluir.</p><p>Puntos clave:<br>1. Transferir es demostrar que el receptor obtiene resultados equivalentes a los del emisor.<br>2. Elija la estrategia según el riesgo: comparativa, covalidación, revalidación o exención justificada.<br>3. Los criterios de aceptación se definen antes de ejecutar y se basan en los datos de validación.</p>"}'::jsonb);
