  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Ejecuta la validación completa de un método HPLC indicador de estabilidad desde el protocolo hasta las conclusiones.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=kiUMizV02_w","provider":"youtube","videoId":"kiUMizV02_w","title":"Validación de Método por HPLC para la Determinación de la Liberación de Diclofenaco en Microcápsulas","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=nAaYOg1o7w4","provider":"youtube","videoId":"nAaYOg1o7w4","title":"MODULO 4: Plan de Verificación de un método HPLC UHPLC","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://database.ich.org/sites/default/files/ICH_Q2%28R2%29_Guideline_2023_1130.pdf","title":"ICH Q2(R2) Validation of Analytical Procedures (Guideline final, 2023)","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: ejecutar de principio a fin la validación de un método HPLC para valoración y sustancias relacionadas, integrando los parámetros y la estadística del curso.</p><p>Caso. Un laboratorio colombiano desarrolla un método HPLC-UV propio para valoración y productos de degradación de tabletas de amlodipino 10 mg (columna C18 150 x 4,6 mm, 5 µm; fase móvil buffer fosfato pH 3,0 : acetonitrilo; detección a 237 nm). Como el método no es farmacopeico, requiere validación completa para el registro sanitario ante el INVIMA.</p><p>Desarrollo por parámetro:<br>1. Especificidad: inyectar blanco, placebo, estándar, muestra y muestras de degradación forzada (ácido, base, oxidación con H2O2, calor y luz según ICH Q1B). Criterio: sin interferencias; resolución de 1,5 o más entre amlodipino y la impureza más cercana; pureza de pico por detector de arreglo de diodos.<br>2. Linealidad: valoración 80–120 % (5 niveles por triplicado); impurezas desde el LC hasta 120 % de la especificación. Criterios: r de 0,999 o más (valoración), residuales aleatorios, intervalo de confianza del intercepto que incluye cero.<br>3. Exactitud: placebo cargado al 80, 100 y 120 % por triplicado (9 determinaciones). Criterio: recuperación de 98,0–102,0 %.<br>4. Precisión: repetibilidad con 6 muestras al 100 % (CV de 2,0 % o menos); precisión intermedia con otro analista, otro día y otro equipo, evaluada con prueba F y t o ANOVA.<br>5. LD y LC para impurezas: relación señal/ruido de 3 y 10, o por la curva (3,3σ/S y 10σ/S), confirmando precisión en el LC.<br>6. Robustez: variaciones deliberadas de pH (±0,2), proporción orgánica (±2 %), temperatura de columna (±5 °C) y flujo (±0,1 mL/min), idealmente con un diseño factorial fraccionado. Los resultados definen los criterios de idoneidad del sistema.<br>7. Idoneidad del sistema: CV de 5 inyecciones de 2,0 % o menos, factor de cola de 2,0 o menos, platos teóricos de 2000 o más y resolución de 1,5 o más.</p><p>Documentación. Protocolo aprobado por aseguramiento de calidad antes de iniciar; datos crudos íntegros (ALCOA+); informe con resultados, desviaciones y conclusión de aptitud; anexos con cromatogramas representativos.</p><p>Puntos clave:<br>1. La degradación forzada es la base de la especificidad de un método indicador de estabilidad.<br>2. Los criterios de aceptación deben definirse en el protocolo, no después de ver los datos.<br>3. La robustez alimenta la idoneidad del sistema que protegerá el método en su uso rutinario.</p>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule)
  VALUES (v_curso, v_unidad, 'Caso UV-Vis: valoración y disolución', 'Clase 4 · Casos prácticos', 7, 'video')
