  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 0, '{"html":"<p>Aplica la validación a un método espectrofotométrico de disolución y reconoce sus limitaciones de especificidad.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=By76UK2eTZI","provider":"youtube","videoId":"By76UK2eTZI","title":"DETERMINACIÓN DE ACETAMINOFÉN EN UN MEDICAMENTO POR ESPECTROSCOPÍA UV-VIS","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 2, '{"source":"enlace","url":"https://www.youtube.com/watch?v=bhk8frZULv8","provider":"youtube","videoId":"bhk8frZULv8","title":"¿Sabes cómo verificar el funcionamiento de tu espectrofotómetro UV-Vis?","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://database.ich.org/sites/default/files/ICH_Q2%28R2%29_Guideline_2023_1130.pdf","title":"ICH Q2(R2) Validation of Analytical Procedures (Guideline final, 2023)","description":"ICH (EN)"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 4, '{"html":"<p>Objetivo: aplicar la validación a un método espectrofotométrico UV-Vis usado para valoración y para cuantificar disolución, reconociendo sus limitaciones de especificidad.</p><p>Caso. Un laboratorio de Bogotá cuantifica paracetamol disuelto en la prueba de disolución de tabletas de 500 mg (medio buffer fosfato pH 5,8, 900 mL, paleta a 50 rpm), midiendo absorbancia a 243 nm. Como el método se adaptó del monógrafo con cambios en la preparación de muestra, se decide una validación parcial orientada al uso: método categoría III (desempeño) según USP &lt;1225&gt;.</p><p>Desarrollo por parámetro:<br>1. Especificidad: el UV-Vis no separa componentes, por lo que se evalúa la contribución del placebo disuelto en el medio (a la concentración equivalente al 100 %). Criterio: interferencia no mayor de 2 % de la absorbancia del estándar. Se recomienda revisar el espectro completo (200–400 nm) para detectar desplazamientos o hombros.<br>2. Linealidad y rango: para disolución, el rango debe cubrir desde aproximadamente 20 % por debajo del valor más bajo esperado hasta 120 % del valor declarado (por ejemplo 10–120 % de la concentración final). Verificar el cumplimiento de la ley de Beer-Lambert: R2 de 0,999 o más y absorbancias idealmente entre 0,2 y 1,0 UA.<br>3. Exactitud: placebo más principio activo en el medio, en tres niveles (por ejemplo 20, 80 y 120 %). Criterio típico: 95–105 %.<br>4. Precisión: repetibilidad de 6 determinaciones y precisión intermedia con otro analista u otro día.<br>5. Estabilidad de la solución: absorbancia de muestras filtradas a 0, 24 y 48 h a temperatura ambiente. Criterio: variación de 2 % o menos.<br>6. Filtración: comparar muestra filtrada con muestra centrifugada, y descartar los primeros mL de filtrado. Criterio: diferencia de 2 % o menos.<br>7. Robustez: variación del pH del medio (±0,05) y longitud de onda (±2 nm).</p><p>Ejemplo de cálculo. Con 5 niveles (10–120 %), pendiente 0,0715 UA·L/mg, intercepto 0,0012 (IC 95 % de −0,004 a 0,006) y R2 = 0,9998, la linealidad se acepta. El placebo aporta 0,6 % de la señal: especificidad aceptable.</p><p>Puntos clave:<br>1. En UV-Vis la especificidad se demuestra por ausencia de contribución del placebo y revisión del espectro.<br>2. En disolución, valide también la filtración y la estabilidad de soluciones.<br>3. Un cambio respecto al método farmacopeico exige al menos una validación parcial documentada.</p>"}'::jsonb);

END
$curso$;
